-- ---------------------------------------------------------------------------------------------------------------------------- grants + policies, generated from the registry
-- Reset first (so the registry is the only source of what the fz roles hold), then grant table by table. A table that does not exist here is skipped.
do $$
declare r record; t regclass; rls_before boolean; rd text; wr text; roles text := 'fz_jarvis, fz_office_agent, fz_auditor';
begin
  execute 'revoke all on all tables in schema public from ' || roles;
  execute 'revoke all on all sequences in schema public from ' || roles;
  for r in select * from public.fz_table_registry order by relname loop
    t := to_regclass('public.' || quote_ident(r.relname));
    continue when t is null;
    execute format('drop policy if exists fz_scope_read on %s', t);
    execute format('drop policy if exists fz_scope_insert on %s', t);
    execute format('drop policy if exists fz_scope_update on %s', t);
    continue when not r.fz_read;
    select c.relrowsecurity into rls_before from pg_class c where c.oid = t;
    if not rls_before then
      execute format('alter table %s enable row level security', t);
      -- Supabase's service_role has BYPASSRLS; this keeps the same "all rows" for it on any Postgres where it does not (the replica), so nothing that works today changes
      if not exists (select 1 from pg_policy p where p.polrelid = t and p.polname = 'fz_service_all') then
        execute format('create policy fz_service_all on %s for all to service_role using (true) with check (true)', t);
      end if;
    end if;
    execute format('grant select on %s to %s', t, roles);
    if r.relname like 'fz\_%' then
      execute format('create policy fz_scope_read on %s for select to %s using ((select public.current_identity()) is not null)', t, roles);
      continue;
    end if;
    rd := case r.scope_column when 'office_id' then format('office_id = any (coalesce((select public.fz_readable_offices(%L)), ''{}''::uuid[]))', r.relname)
                              when 'workspace_id' then format('workspace_id = any (coalesce((select public.fz_readable_workspaces(%L)), ''{}''::uuid[]))', r.relname)
                              when 'workspace_self' then format('id = any (coalesce((select public.fz_readable_workspaces(%L)), ''{}''::uuid[]))', r.relname) end;
    execute format('create policy fz_scope_read on %s for select to %s using (%s)', t, roles, rd);
    wr := format('office_id = any (coalesce((select public.fz_writable_offices(%L)), ''{}''::uuid[]))', r.relname);
    if 'insert' = any (r.fz_write) then
      execute format('grant insert (%s) on %s to fz_jarvis, fz_office_agent', (select string_agg(quote_ident(c), ', ') from unnest(r.fz_insert_columns) c), t);
      execute format('create policy fz_scope_insert on %s for insert to fz_jarvis, fz_office_agent with check (%s and public.fz_agent_in_office(assigned_agent, office_id))', t, wr);
    end if;
    if 'update' = any (r.fz_write) then
      execute format('grant update (%s) on %s to fz_jarvis, fz_office_agent', (select string_agg(quote_ident(c), ', ') from unnest(r.fz_update_columns) c), t);
      execute format('create policy fz_scope_update on %s for update to fz_jarvis, fz_office_agent using (%s) with check (%s and public.fz_agent_in_office(assigned_agent, office_id))', t, wr, wr);
    end if;
  end loop;
end $$;

-- writes by a scoped identity are stamped: an office identity always writes into ITS office, the author is the identity (not a name the caller typed), and no scoped write
-- moves a row to another office
create or replace function public.fz_stamp_scoped_write() returns trigger
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare i record;
begin
  if coalesce(nullif(current_setting('role', true), ''), 'none') not in ('fz_jarvis', 'fz_office_agent', 'fz_auditor') then return new; end if;
  select * into i from public.fz_identity_now();
  if i.slug is null then raise exception 'scoped write refused: no valid identity' using errcode = '42501'; end if;
  if tg_op = 'INSERT' then
    if not i.is_group then new.office_id := i.office_id; end if;
    new.created_by := i.slug;
  else
    if old.mission_id is not null then raise exception 'scoped write refused: mission tasks are changed only by the mission engine' using errcode = '42501'; end if;
    new.office_id := old.office_id;
    new.created_by := old.created_by;
  end if;
  return new;
end $$;
revoke all on function public.fz_stamp_scoped_write() from public, anon, authenticated;
drop trigger if exists tasks_fz_stamp on public.tasks;
create trigger tasks_fz_stamp before insert or update on public.tasks for each row execute function public.fz_stamp_scoped_write();

-- ---------------------------------------------------------------------------------------------------------------------------- per-office permissions (tighten-only overlay)
-- An office row can only be STRICTER than the group policy: it may forbid an action in that office or set a lower per-action / per-day limit. Anyone with the service key
-- may tighten; relaxing an office rule (allow again, raise or remove a limit) needs the signed-in owner. The group policy itself (action_policy) is untouched.
create or replace function public.fz_office_policy_guard() returns trigger
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare g public.action_policy; owner_ok boolean := coalesce(public.is_app_owner(), false);
begin
  if tg_op = 'DELETE' then
    if not owner_ok then raise exception 'only the owner can remove an office rule (it would relax it)' using errcode = '42501'; end if;
    return old;
  end if;
  select * into g from public.action_policy where action = new.action;
  if not found then raise exception 'unknown action %: office rules can only narrow an existing group action', new.action; end if;
  if g.max_cents_per_action is not null and new.max_cents_per_action is not null and new.max_cents_per_action > g.max_cents_per_action then
    raise exception 'office limit $% is above the group limit $%: an office rule can only be stricter', new.max_cents_per_action / 100.0, g.max_cents_per_action / 100.0;
  end if;
  if g.max_count_per_day is not null and new.max_count_per_day is not null and new.max_count_per_day > g.max_count_per_day then
    raise exception 'office daily count % is above the group count %: an office rule can only be stricter', new.max_count_per_day, g.max_count_per_day;
  end if;
  if tg_op = 'UPDATE' and not owner_ok and (
       (new.allowed and not old.allowed)
    or (old.max_cents_per_action is not null and (new.max_cents_per_action is null or new.max_cents_per_action > old.max_cents_per_action))
    or (old.max_count_per_day is not null and (new.max_count_per_day is null or new.max_count_per_day > old.max_count_per_day))) then
    raise exception 'only the owner can relax an office rule' using errcode = '42501';
  end if;
  new.updated_at := now();
  if owner_ok then new.updated_by := 'owner'; end if;
  insert into public.audit_log (actor, action, target, detail)
    values (new.updated_by, 'office_policy_' || lower(tg_op), 'fz_office_action_policy/' || new.office_id || '/' || new.action,
            jsonb_build_object('allowed', new.allowed, 'per_action', new.max_cents_per_action, 'per_day', new.max_count_per_day));
  return new;
end $$;
revoke all on function public.fz_office_policy_guard() from public, anon, authenticated;
drop trigger if exists fz_office_policy_guard on public.fz_office_action_policy;
create trigger fz_office_policy_guard before insert or update or delete on public.fz_office_action_policy for each row execute function public.fz_office_policy_guard();

create or replace function public.fz_set_office_policy(p_office text, p_action text, p_allowed boolean, p_max_cents_per_action integer default null,
                                                       p_max_count_per_day integer default null, p_by text default 'jarvis') returns jsonb
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare o public.fz_offices;
        v_by text := case when coalesce(public.is_app_owner(), false) then 'owner' else 'bot:' || left(coalesce(nullif(btrim(p_by), ''), 'unknown'), 76) end;   -- a caller cannot record itself as the owner
begin
  select * into o from public.fz_offices where slug = p_office and kind = 'office';
  if not found then raise exception 'unknown office %', p_office; end if;
  insert into public.fz_office_action_policy (office_id, action, allowed, max_cents_per_action, max_count_per_day, updated_by)
    values (o.id, p_action, coalesce(p_allowed, false), p_max_cents_per_action, p_max_count_per_day, v_by)
  on conflict (office_id, action) do update set allowed = excluded.allowed, max_cents_per_action = excluded.max_cents_per_action,
    max_count_per_day = excluded.max_count_per_day, updated_by = excluded.updated_by;
  return jsonb_build_object('office', o.slug, 'action', p_action, 'allowed', coalesce(p_allowed, false), 'max_cents_per_action', p_max_cents_per_action, 'max_count_per_day', p_max_count_per_day);
end $$;
revoke all on function public.fz_set_office_policy(text, text, boolean, integer, integer, text) from public, anon, authenticated;

-- Read-only preview of what authorize_action() would decide (same order of rules), WITHOUT consuming an approval or writing anything. A decision that would need an
-- owner approval is always ask_owner here: a scoped identity can never use (burn) an approval, and an allow it gets is never counted toward the caps.
create or replace function public.fz_policy_preview(p_action text, p_cents integer) returns jsonb
language plpgsql stable security definer set search_path to 'pg_catalog' as $$
declare pol public.action_policy; st record; v_today int; v_week int; v_start timestamptz; c int := greatest(coalesce(p_cents, 0), 0);
begin
  select kill_switch, mode into st from public.system_state where id = 1;
  select * into pol from public.action_policy where action = p_action;
  if coalesce(st.kill_switch, true) then return jsonb_build_object('decision', 'deny', 'reason', 'Kill switch is on.', 'tier', pol.tier); end if;
  if pol.action is null then return jsonb_build_object('decision', 'deny', 'reason', 'Unknown action: everything not in the policy is refused.'); end if;
  if pol.tier = 'prohibited' then return jsonb_build_object('decision', 'deny', 'reason', 'Prohibited by policy: ' || pol.description, 'tier', pol.tier); end if;
  if pol.live_only and st.mode = 'dry_run' then return jsonb_build_object('decision', 'deny', 'reason', 'Dry-run mode: external actions are switched off.', 'tier', pol.tier); end if;
  if pol.tier = 'red' or (pol.tier = 'yellow' and st.mode = 'approve_first') then
    return jsonb_build_object('decision', 'ask_owner', 'tier', pol.tier, 'reason', 'Needs the owner''s decision; a scoped identity never uses an approval (the service path does, through authorize_action).');
  end if;
  v_start := date_trunc('day', now() at time zone 'America/Toronto') at time zone 'America/Toronto';
  select count(*) into v_today from public.action_log where action = p_action and decision = 'allow' and at >= v_start;
  select coalesce(sum(cents), 0) into v_week from public.action_log where action = p_action and decision = 'allow' and at >= now() - interval '7 days';
  if pol.max_cents_per_action is not null and c > pol.max_cents_per_action then return jsonb_build_object('decision', 'ask_owner', 'tier', pol.tier, 'reason', 'Over the per-action limit.'); end if;
  if pol.max_count_per_day is not null and v_today >= pol.max_count_per_day then return jsonb_build_object('decision', 'deny', 'tier', pol.tier, 'reason', format('Daily limit reached (%s per day).', pol.max_count_per_day)); end if;
  if pol.max_cents_per_week is not null and v_week + c > pol.max_cents_per_week then return jsonb_build_object('decision', 'ask_owner', 'tier', pol.tier, 'reason', 'Weekly limit would be passed.'); end if;
  return jsonb_build_object('decision', 'allow', 'tier', pol.tier, 'reason', initcap(pol.tier) || ' action within policy (evaluated only: nothing consumed or counted).');
end $$;
revoke all on function public.fz_policy_preview(text, integer) from public, anon, authenticated;

-- The office layer, in one place (also used by the office spend gates of later milestones): why office p_office refuses p_action for p_cents now, or NULL.
-- Refuses when the office is not active, or an office rule forbids the action, sets a lower per-action limit, or its daily count is reached (allows of this action
-- logged with detail.office = the office). The caller takes the 7332 lock first. Read-only.
create or replace function public.fz_office_refusal(p_office uuid, p_action text, p_cents integer) returns text
language plpgsql stable security definer set search_path to 'pg_catalog' as $$
declare o public.fz_offices; op public.fz_office_action_policy; v_today int; v_start timestamptz; v_cents int := greatest(coalesce(p_cents, 0), 0);
begin
  select * into o from public.fz_offices where id = p_office;
  if not found then return 'Unknown office: refused.'; end if;
  if o.kind <> 'office' then return null; end if;                        -- the group itself has no office layer
  if o.status <> 'active' then return format('Office %s is %s: its actions are refused until the owner activates it.', o.title, o.status); end if;
  select * into op from public.fz_office_action_policy where office_id = o.id and action = p_action;
  if not found then return null; end if;
  if not op.allowed then return format('Not allowed in office %s (office rule).', o.title); end if;
  if op.max_cents_per_action is not null and v_cents > op.max_cents_per_action then
    return format('Over the %s office limit ($%s > $%s).', o.title, v_cents / 100.0, op.max_cents_per_action / 100.0);
  end if;
  if op.max_count_per_day is not null then
    v_start := date_trunc('day', now() at time zone 'America/Toronto') at time zone 'America/Toronto';
    select count(*) into v_today from public.action_log where action = p_action and decision = 'allow' and at >= v_start and detail ->> 'office' = o.slug;
    if v_today >= op.max_count_per_day then return format('Office %s daily limit reached (%s per day).', o.title, op.max_count_per_day); end if;
  end if;
  return null;
end $$;
revoke all on function public.fz_office_refusal(uuid, text, integer) from public, anon, authenticated;

-- The office-aware gate. Office layer first (can only refuse). Then:
--   a SCOPED caller (fz roles) gets fz_policy_preview(): evaluate only. It never consumes an owner approval and never writes an allow row (allows count toward the caps);
--     only refusals are logged. The real action still goes through authorize_action() on the service path when it is carried out.
--   the SERVICE path calls the UNCHANGED authorize_action() for the group decision (kill switch, mode, tiers, approvals, caps), exactly as calling it directly would.
-- A scoped caller cannot choose who it is: the actor is its identity and an office identity's office is its own. The auditor cannot act.
create or replace function public.fz_authorize_action(p_action text, p_cents integer default 0, p_ref text default null, p_office text default null, p_actor text default null,
                                                      p_venture uuid default null, p_mission uuid default null, p_detail jsonb default '{}'::jsonb) returns jsonb
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare r text := coalesce(nullif(current_setting('role', true), ''), 'none'); i record; o public.fz_offices;
        v_actor text; v_ident text; v_reason text; v_cents int := greatest(coalesce(p_cents, 0), 0); res jsonb;
begin
  if r in ('fz_jarvis', 'fz_office_agent', 'fz_auditor') then
    select * into i from public.fz_identity_now();
    if i.slug is null then raise exception 'no valid scoped identity for this token' using errcode = '42501'; end if;
    if i.db_role = 'fz_auditor' then raise exception 'the auditor identity is read-only' using errcode = '42501'; end if;
    v_actor := i.slug; v_ident := i.slug;
    if not i.is_group then
      if p_office is not null and p_office is distinct from i.office_slug then raise exception 'office mismatch: this identity acts only for %', i.office_slug using errcode = '42501'; end if;
      select * into o from public.fz_offices where id = i.office_id;
    elsif p_office is not null then
      select * into o from public.fz_offices where slug = p_office;
      if not found then raise exception 'unknown office %', p_office; end if;
    end if;
  else
    v_actor := nullif(btrim(coalesce(p_actor, '')), '');
    if v_actor is null then raise exception 'p_actor is required'; end if;
    if p_office is not null then
      select * into o from public.fz_offices where slug = p_office;
      if not found then raise exception 'unknown office %', p_office; end if;
    end if;
  end if;
  if o.id is not null and o.kind = 'office' then
    perform pg_advisory_xact_lock(7332);                                  -- the same lock authorize_action takes: office counts and the group decision are one critical section
    v_reason := public.fz_office_refusal(o.id, p_action, v_cents);
    if v_reason is not null then
      insert into public.action_log (actor, action, tier, decision, reason, cents, venture_id, mission_id, ref, detail)
        values (v_actor, p_action, (select tier from public.action_policy where action = p_action), 'deny', v_reason, v_cents, p_venture, p_mission, p_ref,
                coalesce(p_detail, '{}'::jsonb) || jsonb_build_object('office', o.slug, 'identity', coalesce(v_ident, 'service'), 'layer', 'office'));
      return jsonb_build_object('decision', 'deny', 'reason', v_reason, 'tier', (select tier from public.action_policy where action = p_action), 'office', o.slug);
    end if;
  end if;
  if v_ident is not null then
    res := public.fz_policy_preview(p_action, v_cents) || jsonb_build_object('evaluated_only', true);
    if res ->> 'decision' <> 'allow' then                                -- a refusal / ask is logged (it never counts toward a cap); an allow is not
      insert into public.action_log (actor, action, tier, decision, reason, cents, venture_id, mission_id, ref, detail)
        values (v_actor, p_action, res ->> 'tier', res ->> 'decision', res ->> 'reason', v_cents, p_venture, p_mission, p_ref,
                coalesce(p_detail, '{}'::jsonb) || jsonb_build_object('office', coalesce(o.slug, 'group'), 'identity', v_ident, 'layer', 'scoped_preview'));
    end if;
    return res || jsonb_build_object('office', coalesce(o.slug, 'group'));
  end if;
  res := public.authorize_action(v_actor, p_action, v_cents, p_ref, p_venture, p_mission,
                                 coalesce(p_detail, '{}'::jsonb) || jsonb_build_object('office', coalesce(o.slug, 'group'), 'identity', 'service'));
  return res || jsonb_build_object('office', coalesce(o.slug, 'group'));
end $$;
revoke all on function public.fz_authorize_action(text, integer, text, text, text, uuid, uuid, jsonb) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------------------------------------- owner-only controls
create or replace function public.fz_owner_set_office_status(p_office text, p_status text) returns jsonb
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare o public.fz_offices;
begin
  if not coalesce(public.is_app_owner(), false) then raise exception 'owner approval required: this action is refused for the bot' using errcode = '42501'; end if;
  if p_status not in ('dormant', 'active', 'paused', 'closed') then raise exception 'status must be dormant, active, paused or closed'; end if;
  update public.fz_offices set status = p_status, updated_at = now(), updated_by = 'owner' where slug = p_office and kind = 'office' returning * into o;
  if not found then raise exception 'unknown office %', p_office; end if;
  insert into public.audit_log (actor, action, target, detail) values ('owner', 'office_status', 'fz_offices/' || o.slug, jsonb_build_object('status', p_status));
  return jsonb_build_object('office', o.slug, 'status', o.status);
end $$;
revoke all on function public.fz_owner_set_office_status(text, text) from public, anon, authenticated;

-- activate / revoke an identity; pin a token id; or void every token issued so far (p_void_tokens)
create or replace function public.fz_owner_set_identity(p_identity text, p_status text, p_token_jti text default null, p_void_tokens boolean default false) returns jsonb
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare x public.fz_identities;
begin
  if not coalesce(public.is_app_owner(), false) then raise exception 'owner approval required: this action is refused for the bot' using errcode = '42501'; end if;
  if p_status not in ('dormant', 'active', 'revoked') then raise exception 'status must be dormant, active or revoked'; end if;
  update public.fz_identities set status = p_status, token_jti = coalesce(nullif(btrim(p_token_jti), ''), token_jti),
         tokens_valid_after = case when p_void_tokens then now() else tokens_valid_after end, updated_at = now(), updated_by = 'owner'
   where slug = p_identity and kind <> 'owner' returning * into x;
  if not found then raise exception 'unknown identity %', p_identity; end if;
  insert into public.audit_log (actor, action, target, detail)
    values ('owner', 'identity_status', 'fz_identities/' || x.slug, jsonb_build_object('status', p_status, 'jti_pinned', x.token_jti is not null, 'tokens_voided', p_void_tokens));
  return jsonb_build_object('identity', x.slug, 'status', x.status, 'jti_pinned', x.token_jti is not null, 'tokens_valid_after', x.tokens_valid_after);
end $$;
revoke all on function public.fz_owner_set_identity(text, text, text, boolean) from public, anon, authenticated;

-- move a client workspace (and so all its ws_* / ffm_* rows) to another office
create or replace function public.fz_owner_set_workspace_office(p_workspace uuid, p_office text) returns jsonb
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare o public.fz_offices;
begin
  if not coalesce(public.is_app_owner(), false) then raise exception 'owner approval required: this action is refused for the bot' using errcode = '42501'; end if;
  select * into o from public.fz_offices where slug = p_office and kind = 'office';
  if not found then raise exception 'unknown office %', p_office; end if;
  if not exists (select 1 from public.client_workspaces where id = p_workspace) then raise exception 'unknown workspace'; end if;
  insert into public.fz_workspace_offices (workspace_id, office_id, assigned_by, assigned_at) values (p_workspace, o.id, 'owner', now())
  on conflict (workspace_id) do update set office_id = excluded.office_id, assigned_by = 'owner', assigned_at = now();
  insert into public.audit_log (actor, action, target, detail) values ('owner', 'workspace_office', 'client_workspaces/' || p_workspace, jsonb_build_object('office', o.slug));
  return jsonb_build_object('workspace', p_workspace, 'office', o.slug);
end $$;
revoke all on function public.fz_owner_set_workspace_office(uuid, text) from public, anon, authenticated;

-- the bot may only ever make an identity SAFER (fail closed): revoke it or void its tokens. It can never activate one.
create or replace function public.fz_revoke_identity(p_identity text, p_reason text) returns jsonb
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare x public.fz_identities;
begin
  update public.fz_identities set status = 'revoked', tokens_valid_after = now(), updated_at = now(), updated_by = 'revoke'
   where slug = p_identity and kind not in ('owner', 'backup_reader') returning * into x;
  if not found then raise exception 'unknown identity %', p_identity; end if;
  insert into public.audit_log (actor, action, target, detail) values ('jarvis', 'identity_revoked', 'fz_identities/' || x.slug, jsonb_build_object('reason', left(coalesce(p_reason, ''), 300)));
  return jsonb_build_object('identity', x.slug, 'status', x.status);
end $$;
revoke all on function public.fz_revoke_identity(text, text) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------------------------------------- org re-seed (runs ONCE; every decision logged)
-- Mapping: every existing client workspace -> ff-marketing (fz_workspace_offices; every ws_* / ffm_* row follows its workspace); everything else is the group (column defaults).
-- Archive = an archived_at STAMP only. No status changes at apply time: nothing that runs today stops because of this migration. Pausing an archived row is a later owner
-- action (fz_reseed_preview() shows the list first). A row is NOT archived when something live uses it:
--   agents      named by live code (bot.py, hq_engine, hq_missions, hq_llm, hq_hands, hq_ffm_run, hq_mail, hq_meter, hq_commands), open tasks, a model call in the last 14 days,
--               or belonging to / managing a kept venture
--   ventures    the mission engine's venture teams (idea-lab, donna, real-estate, day-job-sales), status active or proposed (an open owner decision), or open tasks / live missions
--   departments holding / research, a kept agent in it, or its venture kept
create or replace function public.fz_reseed_decisions() returns table (entity text, key text, decision text, status text, reason text)
language plpgsql stable security definer set search_path to 'pg_catalog' as $$
declare
  live_agents text[] := array['jarvis', 'jarvis-chat', 'jarvis-core', 'jarvis-hands', 'builder', 'research', 'auditor', 'compliance-qa', 'mission-manager', 'donna-ops',
                              'new-ventures-researcher', 'new-ventures-auditor', 'donna-researcher', 'donna-auditor', 'real-estate-researcher', 'real-estate-auditor',
                              'day-job-sales-researcher', 'day-job-sales-auditor'];
  live_ventures text[] := array['idea-lab', 'donna', 'real-estate', 'day-job-sales'];
  kept_v uuid[] := '{}'; kept_vslug text[] := '{}'; kept_a text[] := '{}'; v record; why text;
begin
  for v in select * from public.ventures x order by x.slug loop
    why := case
      when v.slug = any (live_ventures) then 'mission engine venture team (hq_missions.VENTURE_TEAM)'
      when v.status = 'active' then 'active venture'
      when v.status = 'proposed' then 'proposed: an open owner decision'
      when exists (select 1 from public.tasks t where t.venture_id = v.id and t.status in ('todo', 'doing', 'blocked')) then 'has open tasks'
      when exists (select 1 from public.missions m where m.venture_id = v.id and m.status not in ('completed', 'rejected', 'abandoned', 'failed')) then 'has a live mission'
    end;
    if why is not null then kept_v := kept_v || v.id; kept_vslug := kept_vslug || v.slug; end if;
    entity := 'venture'; key := v.slug; status := v.status; decision := case when why is null then 'archived' else 'kept' end; reason := coalesce(why, 'old plan, not live (status ' || v.status || ')');
    return next;
  end loop;
  for v in select * from public.agents x order by x.slug loop
    why := case
      when v.slug = any (live_agents) then 'used by live code'
      when exists (select 1 from public.tasks t where t.assigned_agent = v.slug and t.status in ('todo', 'doing', 'blocked')) then 'has open tasks'
      when exists (select 1 from public.llm_calls c where c.agent_slug = v.slug and c.started_at > now() - interval '14 days') then 'made a model call in the last 14 days'
      when v.venture_id = any (kept_v) or exists (select 1 from public.ventures x where x.manager_agent = v.slug and x.id = any (kept_v)) then 'belongs to or manages a kept venture'
    end;
    if why is not null then kept_a := kept_a || v.slug; end if;
    entity := 'agent'; key := v.slug; status := v.status; decision := case when why is null then 'archived' else 'kept' end; reason := coalesce(why, 'old plan, not live');
    return next;
  end loop;
  for v in select * from public.departments x order by x.slug loop
    why := case
      when v.slug in ('holding', 'research') then 'core department (holding / research)'
      when exists (select 1 from public.agents a where a.department_slug = v.slug and a.slug = any (kept_a)) then 'a kept agent works in it'
      when v.venture_id = any (kept_v) then 'its venture is kept'
    end;
    entity := 'department'; key := v.slug; status := v.status; decision := case when why is null then 'archived' else 'kept' end; reason := coalesce(why, 'old plan, not live');
    return next;
  end loop;
end $$;
revoke all on function public.fz_reseed_decisions() from public, anon, authenticated;

-- read-only: what the rule archives on TODAY's data (before apply: run the function body by hand; after apply: what a new pass would add). Owner input for any later pausing.
create or replace function public.fz_reseed_preview() returns table (entity text, key text, status text, reason text, already_logged boolean)
language sql stable security definer set search_path to 'pg_catalog' as $$
  select d.entity, d.key, d.status, d.reason, exists (select 1 from public.fz_org_archive a where a.entity = d.entity and a.key = d.key)
    from public.fz_reseed_decisions() d where d.decision = 'archived' order by 1, 2
$$;
revoke all on function public.fz_reseed_preview() from public, anon, authenticated;

do $$
declare n_arch int; n_kept int;
begin
  if exists (select 1 from public.fz_org_archive where entity = 'reseed') then return; end if;
  insert into public.fz_workspace_offices (workspace_id, office_id) select id, 'f0000000-0000-4000-8000-000000000007' from public.client_workspaces on conflict do nothing;
  create temp table fz_d on commit drop as select * from public.fz_reseed_decisions();
  insert into public.fz_org_archive (entity, key, decision, prior_status, new_status, reason) select entity, key, decision, status, status, reason from fz_d;
  update public.ventures x set archived_at = now() from fz_d d where d.entity = 'venture' and d.decision = 'archived' and d.key = x.slug;
  update public.agents x set archived_at = now() from fz_d d where d.entity = 'agent' and d.decision = 'archived' and d.key = x.slug;
  update public.departments x set archived_at = now() from fz_d d where d.entity = 'department' and d.decision = 'archived' and d.key = x.slug;
  select count(*) filter (where decision = 'archived'), count(*) filter (where decision = 'kept') into n_arch, n_kept from fz_d;
  drop table fz_d;
  insert into public.fz_org_archive (entity, key, decision, reason) values ('reseed', 'm1', 'run', format('%s archived (stamp only, no status change), %s kept', n_arch, n_kept));
  insert into public.audit_log (actor, action, target, detail) values ('migration', 'org_reseed', 'fz_org_archive', jsonb_build_object('archived', n_arch, 'kept', n_kept, 'status_changes', 0));
end $$;

-- ---------------------------------------------------------------------------------------------------------------------------- reports
create or replace function public.fz_unregistered_tables() returns setof text
language sql stable security definer set search_path to 'pg_catalog' as $$
  select c.relname::text from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind in ('r', 'p')
     and not exists (select 1 from public.fz_table_registry g where g.relname = c.relname) order by 1
$$;
revoke all on function public.fz_unregistered_tables() from public, anon, authenticated;

create or replace function public.fz_org_status() returns jsonb
language plpgsql stable security definer set search_path to 'pg_catalog' as $$
declare orphans jsonb := '{}'::jsonb; t text; v_n bigint;
begin
  foreach t in array array['agents', 'departments', 'ventures', 'missions', 'tasks', 'memory'] loop
    execute format('select count(*) from public.%I x where not exists (select 1 from public.fz_offices o where o.id = x.office_id)', t) into v_n;
    if v_n > 0 then orphans := orphans || jsonb_build_object(t, v_n); end if;
  end loop;
  return jsonb_build_object(
    'offices', (select jsonb_agg(jsonb_build_object('slug', slug, 'title', title, 'status', status) order by kind, slug) from public.fz_offices),
    'identities', (select jsonb_agg(jsonb_build_object('slug', slug, 'kind', kind, 'status', status, 'role', db_role) order by slug) from public.fz_identities),
    'archive', (select jsonb_object_agg(entity || ':' || decision, n) from (select entity, decision, count(*) n from public.fz_org_archive where entity <> 'reseed' group by 1, 2) a),
    'registry', (select jsonb_object_agg(scope, n) from (select scope, count(*) n from public.fz_table_registry group by 1) s),
    'unregistered_tables', coalesce((select jsonb_agg(x) from public.fz_unregistered_tables() x), '[]'::jsonb),
    'orphan_office_ids', orphans,
    'client_workspaces', (select jsonb_object_agg(o, n) from (select coalesce((select f.slug from public.fz_offices f where f.id = m.office_id), 'ff-marketing (default)') o, count(*) n
                                                                 from public.client_workspaces w left join public.fz_workspace_offices m on m.workspace_id = w.id group by 1) x));
end $$;
revoke all on function public.fz_org_status() from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------------------------------------- function grants for the scoped roles (allowlist)
-- Start from nothing, then grant exactly the helpers the policies call plus the identity's own tools. No approval, owner, money, consent or backup function is here.
do $$
declare f regprocedure;
begin
  for f in select p.oid::regprocedure from pg_proc p where p.pronamespace = 'public'::regnamespace and p.prokind in ('f', 'p') loop
    execute format('revoke all on routine %s from fz_jarvis, fz_office_agent, fz_auditor', f);
  end loop;
end $$;
grant execute on function public.fz_claims(), public.fz_identity_now(), public.current_identity(), public.current_office(), public.current_office_id(), public.is_group_scope(),
  public.fz_readable_offices(text), public.fz_writable_offices(text), public.fz_readable_workspaces(text), public.fz_whoami(), public.fz_agent_in_office(text, uuid)
  to fz_jarvis, fz_office_agent, fz_auditor;
grant execute on function public.fz_authorize_action(text, integer, text, text, text, uuid, uuid, jsonb) to fz_jarvis, fz_office_agent;

-- ---------------------------------------------------------------------------------------------------------------------------- backup classification (PROTECTED: owner approval)
-- Same rows as 20261124_jarvis_hands_v1 (unchanged, same order) plus the six fz_* tables. Without this the backup fails closed on unclassified tables.
create or replace function public.backup_classification() returns table (table_name text, data_class text, note text)
language sql immutable set search_path to 'pg_catalog' as $$
  select * from (values
    -- public: non-personal reference data
    ('model_prices', 'public', 'published model prices'),
    -- secret: never exported, never in any backup
    ('push_config', 'secret', 'private push keys'),
    ('push_subscriptions', 'secret', 'push endpoints and keys'),
    -- client_pii: third-party personal data (leads, prospects, replies, setters, suppression list). EXCLUDED until retention, access, deletion and key policy are set.
    ('leads', 'client_pii', 'prospect name, phone, email, notes'),
    ('outbox', 'client_pii', 'drafts and recipients (to_ref) for leads'),
    ('lead_replies', 'client_pii', 'free-text notes about replies from leads'),
    ('deals', 'client_pii', 'notes about leads; references leads'),
    ('contact_suppressions', 'client_pii', 'opted-out email addresses. After a restore from an off-site backup this list is EMPTY: restore it from the database provider backup before any outreach is ever enabled'),
    ('setters', 'client_pii', 'sales partner name and contact'),
    ('setter_events', 'client_pii', 'client names per setter event'),
    ('setter_payouts', 'client_pii', 'references setters'),
    ('client_workspaces', 'client_pii', 'client company names'),
    -- internal: operating data of the owner and the ventures
    ('account_requests', 'internal', 'vendor sign-up requests; login name only, never a password'),
    ('accounts_registry', 'internal', 'which service accounts exist; vault reference only'),
    ('action_log', 'internal', 'action audit'), ('action_policy', 'internal', 'autonomy tiers'), ('agent_runs', 'internal', 'run summaries (free text)'),
    ('agents', 'internal', 'agent definitions'), ('alert_state', 'internal', 'alert throttling'), ('app_owners', 'internal', 'owner login emails'),
    ('approval_requests', 'internal', 'approvals'), ('audit_log', 'internal', 'audit trail (free text in detail)'), ('bank_accounts', 'internal', 'owner own bank labels and last4'),
    ('bank_balances', 'internal', 'owner own balances'), ('bank_transactions', 'internal', 'owner own transactions'), ('build_requests', 'internal', 'build queue'),
    ('capital_policy', 'internal', 'spend limits'), ('company_profile', 'internal', 'sender identity of the owner ventures'), ('dayjob_days', 'internal', 'day job counters'),
    ('dayjob_targets', 'internal', 'day job targets'), ('departments', 'internal', 'org'), ('escalations', 'internal', 'escalations (free text)'),
    ('evidence_sources', 'internal', 'fetched public web pages'), ('executor_registry', 'internal', 'executor limits'), ('executor_runs', 'internal', 'executor audit'),
    ('handbook', 'internal', 'handbook'), ('human_handoffs', 'internal', 'tasks for the owner (free text)'), ('ideas', 'internal', 'ideas'),
    ('integration_status', 'internal', 'integration health'), ('ledger', 'internal', 'books'), ('llm_calls', 'internal', 'model call meter'),
    ('memory', 'internal', 'agent memory (free text)'), ('mission_outcomes', 'internal', 'outcomes'), ('missions', 'internal', 'missions (free text)'),
    ('org_changes', 'internal', 'org proposals'), ('owner_messages', 'internal', 'messages to the owner (free text)'), ('payment_instructions', 'internal', 'payment requests; payee may be a person'),
    ('predictions', 'internal', 'predictions'), ('reconciliation_flags', 'internal', 'reconciliation'), ('setter_terms', 'internal', 'setter commission terms'),
    ('spend_reservations', 'internal', 'spend gateway'), ('system_state', 'internal', 'kill switch and modes'), ('systems', 'internal', 'registered systems'),
    ('tasks', 'internal', 'tasks (free text)'), ('tool_registry', 'internal', 'tools'), ('venture_assets', 'internal', 'assets'), ('venture_config', 'internal', 'venture offer config'),
    ('venture_goals', 'internal', 'goals'), ('venture_procedures', 'internal', 'procedures'), ('ventures', 'internal', 'ventures'), ('waterfall_policy', 'internal', 'money waterfall'),
    ('web_messages', 'internal', 'owner chat (free text)'),
    -- Jarvis core v2 (20261123). Class 'secret' = NOT in the off-site export (the database provider's own backups still hold them). Reason: the leak-redaction
    -- export needs a reviewed backup_redaction_spec() entry for every exported text column; until those are written (follow-up, protected) the safe choice is to keep
    -- these operational tables out of the off-site file. They hold no client data by design; jarvis_result_cache may.
    ('jarvis_core_config', 'secret', 'Jarvis core switches; off-site export pending a reviewed redaction spec'), ('jarvis_jobs', 'secret', 'job queue; off-site export pending a reviewed redaction spec'),
    ('jarvis_job_events', 'secret', 'append-only queue audit; off-site export pending a reviewed redaction spec'), ('jarvis_task_stats', 'secret', 'run counts per task class; off-site export pending'),
    ('jarvis_changelog', 'secret', 'append-only changelog; off-site export pending'), ('jarvis_call_log', 'secret', 'append-only emergency-call ledger (no phone numbers); off-site export pending'),
    ('jarvis_large_approvals', 'secret', 'owner approvals for the large model tier; off-site export pending'), ('jarvis_self_fund_credits', 'secret', 'owner-confirmed Jarvis revenue (amounts only); off-site export pending'),
    ('jarvis_agent_wakes', 'secret', 'append-only agent wake / sleep log; off-site export pending'),
    ('jarvis_result_cache', 'secret', 'cached task output; may contain client data, never exported (rebuilt on demand)'),
    ('jarvis_call_criteria', 'secret', 'the owner-approved emergency-call events (copy of ops/CRITICAL_EVENTS.json); off-site export pending'),
    ('jarvis_seed_staging', 'secret', 'owner profile import staged by the bot until the owner applies it; private, never exported'),
    -- Jarvis hands v1 (20261124): metadata only, no secrets (vault references are ids; tokens and passwords live only in the vault)
    ('hand_connectors', 'internal', 'connector registry and owner settings'), ('hand_accounts', 'internal', 'which accounts exist; vault references only, no secrets'),
    ('hand_actions', 'internal', 'action and content queue (payload free text is not exported)'), ('hand_standing', 'internal', 'owner standing approvals'),
    -- Org & Access M1 (20261127): org registry. Class 'secret' = not in the off-site export (as Jarvis core): the offices, identities and table registry are re-seeded by the
    -- migration (statuses come back DORMANT, which is the safe state); exporting them needs reviewed backup_redaction_spec() rows first (follow-up, protected).
    ('fz_offices', 'secret', 'the group and the eight offices; re-seeded by the migration; off-site export pending a reviewed redaction spec'),
    ('fz_identities', 'secret', 'identity registry (status, pinned token ids); re-seeded by the migration'),
    ('fz_table_registry', 'secret', 'table classification; re-seeded by the migration'),
    ('fz_workspace_offices', 'secret', 'which office serves each client workspace; off-site export pending'),
    ('fz_office_action_policy', 'secret', 'per-office tighten-only permission overlay; off-site export pending'),
    ('fz_org_archive', 'secret', 'append-only log of the org re-seed decisions; off-site export pending')
  ) v (table_name, data_class, note)
$$;
revoke all on function public.backup_classification() from public, anon, authenticated;
reset lock_timeout;

-- ===== 20261128_office_money_v1.sql =====
-- FENDEZY GROUP Phase 1, milestone M2 "Office money": virtual sub-ledgers per office + owner-controlled capital allocation. ADDITIVE. Needs 20261127_org_access_v1 (M1).
-- Design (docs/architecture/PHASE1_M2_OFFICE_MONEY.md has the full write-up):
--   * ONE real bank account (the group's). An office's money is ACCOUNTING ATTRIBUTION only: allocations the owner made to it, and the ledger / AI / reserved spend
--     and the received revenue attributed to it. Nothing here moves money, writes the ledger, or changes a cap, the kill switch, dry run, mode, authorize_action,
--     action_policy, reserve_spend / settle_spend / capital_snapshot or any executor. No trigger is added to any existing table.
--   * fz_office_allocations: append-only allocate / clawback events. Written ONLY by the signed-in owner (is_app_owner(); the bot and every API role are refused,
--     also by a table trigger). Every office starts at $0. An allocation can never exceed the group's unallocated real capital (capital_snapshot).
--   * fz_office_money_proposals: the bot / Jarvis may PROPOSE an allocation, a clawback or a reinvestment rule; only the owner executes or rejects it.
--   * fz_office_money_policy: the per-office reinvestment rule (owner only). No row = 0 % (dormant): an office never keeps profit until the owner says so.
--   * fz_money_attribution: which office each ledger row / model call / spend reservation belongs to, stamped once (by the office spend gate, or by fz_money_stamp()
--     from the row's venture or agent office). Rows from before this migration (the cutover) are the group's. Only the owner re-attributes.
--   * fz_office_money (view): per office allocated, spent, revenue, profit, available. Scoped office identities read their OWN row only; Jarvis and the auditor read all.
--   * fz_reserve_office_spend(): an office layer IN FRONT OF the unchanged reserve_spend(). It can only refuse (dormant office, office balance short); otherwise it
--     returns exactly what reserve_spend() decides. Service path only: no scoped identity can call it (and it refuses one even if a grant were added later),
--     so a scoped caller can never consume an owner approval.
-- Ordered BEFORE the lockdown (R3), like M1: it grants only to the fz roles (select on two views) and service_role; every fz_owner_* function checks is_app_owner().
-- Rollback: ops/rollback_office_money.sql. Safe to re-run.

set lock_timeout = '5s';

-- ---------------------------------------------------------------------------------------------------------------------------- tables
create table if not exists public.fz_money_config (
  id int primary key default 1 check (id = 1),
  cutover_at timestamptz not null default now(),                         -- ledger / AI / reservation rows before this are the group's (attribution starts here)
  created_at timestamptz not null default now()
);
-- re-applying never moves the cutover; after a rollback (which archives this table into fz_archive) the archived cutover is reused (review fix 3)
do $$
begin
  if to_regclass('fz_archive.fz_money_config') is not null then
    execute 'insert into public.fz_money_config (id, cutover_at, created_at) select id, cutover_at, created_at from fz_archive.fz_money_config where id = 1 on conflict (id) do nothing';
  end if;
end $$;
insert into public.fz_money_config (id) values (1) on conflict (id) do nothing;

create table if not exists public.fz_office_allocations (
  id bigint generated always as identity primary key,
  office_id uuid not null,                                               -- no foreign key (fz_offices is not exported; M1 lesson)
  kind text not null check (kind in ('allocate', 'clawback')),
  cents integer not null check (cents > 0),
  reason text not null check (length(btrim(reason)) between 3 and 500),
  proposal_id uuid,
  by text not null default 'owner',
  at timestamptz not null default now()
);
create index if not exists fz_office_allocations_office on public.fz_office_allocations (office_id);

create table if not exists public.fz_office_money_policy (
  office_id uuid primary key,
  reinvest_pct integer not null default 0 check (reinvest_pct between 0 and 100),
  updated_by text not null default 'owner',
  updated_at timestamptz not null default now()
);

create table if not exists public.fz_office_money_proposals (
  id uuid primary key default gen_random_uuid(),
  office_id uuid not null,
  kind text not null check (kind in ('allocate', 'clawback', 'reinvest')),
  cents integer check (cents is null or cents > 0),
  reinvest_pct integer check (reinvest_pct is null or reinvest_pct between 0 and 100),
  rationale text not null check (length(btrim(rationale)) between 10 and 2000),
  proposed_by text not null,
  status text not null default 'pending' check (status in ('pending', 'executed', 'rejected', 'expired')),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '7 days',
  decided_at timestamptz,
  decided_by text,
  result jsonb,
  check ((kind = 'reinvest' and reinvest_pct is not null and cents is null) or (kind <> 'reinvest' and cents is not null and reinvest_pct is null))
);
create index if not exists fz_office_money_proposals_pending on public.fz_office_money_proposals (office_id) where status = 'pending';

create table if not exists public.fz_money_attribution (
  source text not null check (source in ('ledger', 'llm_call', 'reservation')),
  source_id uuid not null,
  office_id uuid not null,
  how text not null check (how in ('office_gate', 'reservation', 'venture', 'agent', 'group', 'owner')),
  by text not null default 'stamp',
  at timestamptz not null default now(),
  primary key (source, source_id)
);
create index if not exists fz_money_attribution_office on public.fz_money_attribution (office_id);

do $$
declare t text;
begin
  foreach t in array array['fz_money_config', 'fz_office_allocations', 'fz_office_money_policy', 'fz_office_money_proposals', 'fz_money_attribution'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from public, anon, authenticated, service_role, fz_jarvis, fz_office_agent, fz_auditor', t);
  end loop;
end $$;
-- the bot reads the raw tables; it never writes them (only the functions below do, as their owner)
grant select on public.fz_money_config, public.fz_office_allocations, public.fz_office_money_policy, public.fz_office_money_proposals, public.fz_money_attribution to service_role;
revoke all on sequence public.fz_office_allocations_id_seq from public, anon, authenticated, service_role;

-- ---------------------------------------------------------------------------------------------------------------------------- guards
-- writes only by the signed-in owner (a direct database session without the owner's auth uid is refused too)
create or replace function public.fz_money_owner_only() returns trigger
language plpgsql security definer set search_path to 'pg_catalog' as $$
begin
  if not coalesce(public.is_app_owner(), false) then
    raise exception 'owner approval required: % is written by the signed-in owner only', tg_relname using errcode = '42501';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;
revoke all on function public.fz_money_owner_only() from public, anon, authenticated;

-- proposals: inserted by fz_propose_office_money(); decided only by the owner. The one non-owner change: a pending proposal past its expiry may be marked expired (safer).
create or replace function public.fz_money_proposal_guard() returns trigger
language plpgsql security definer set search_path to 'pg_catalog' as $$
begin
  if tg_op = 'DELETE' then raise exception 'proposals are never deleted' using errcode = '42501'; end if;
  if tg_op = 'INSERT' then
    if new.status <> 'pending' or new.decided_at is not null or new.result is not null then raise exception 'a proposal starts pending' using errcode = '42501'; end if;
    return new;
  end if;
  if coalesce(public.is_app_owner(), false) then
    if old.status <> 'pending' then raise exception 'proposal % is already %', old.id, old.status; end if;
    return new;
  end if;
  if old.status = 'pending' and new.status = 'expired' and old.expires_at <= now()
     and (to_jsonb(new) - 'status' - 'decided_at' - 'decided_by') = (to_jsonb(old) - 'status' - 'decided_at' - 'decided_by') then
    return new;
  end if;
  raise exception 'owner approval required: only the owner decides a money proposal' using errcode = '42501';
end $$;
revoke all on function public.fz_money_proposal_guard() from public, anon, authenticated;

-- attribution: stamped once; only the owner re-attributes; never deleted
create or replace function public.fz_money_attribution_guard() returns trigger
language plpgsql security definer set search_path to 'pg_catalog' as $$
begin
  if tg_op = 'DELETE' then raise exception 'attribution is never deleted' using errcode = '42501'; end if;
  if not coalesce(public.is_app_owner(), false) then raise exception 'owner approval required: only the owner re-attributes money' using errcode = '42501'; end if;
  return new;
end $$;
revoke all on function public.fz_money_attribution_guard() from public, anon, authenticated;

drop trigger if exists fz_office_allocations_owner on public.fz_office_allocations;
create trigger fz_office_allocations_owner before insert on public.fz_office_allocations for each row execute function public.fz_money_owner_only();
drop trigger if exists fz_office_allocations_append_only on public.fz_office_allocations;
create trigger fz_office_allocations_append_only before update or delete on public.fz_office_allocations for each row execute function public.fz_append_only();
drop trigger if exists fz_office_money_policy_owner on public.fz_office_money_policy;
create trigger fz_office_money_policy_owner before insert or update or delete on public.fz_office_money_policy for each row execute function public.fz_money_owner_only();
drop trigger if exists fz_office_money_proposals_guard on public.fz_office_money_proposals;
create trigger fz_office_money_proposals_guard before insert or update or delete on public.fz_office_money_proposals for each row execute function public.fz_money_proposal_guard();
drop trigger if exists fz_money_attribution_guard on public.fz_money_attribution;
create trigger fz_money_attribution_guard before update or delete on public.fz_money_attribution for each row execute function public.fz_money_attribution_guard();
do $$
declare t text;
begin
  foreach t in array array['fz_office_allocations', 'fz_office_money_proposals', 'fz_money_attribution', 'fz_money_config'] loop
    execute format('drop trigger if exists %I on public.%I', t || '_no_truncate', t);
    execute format('create trigger %I before truncate on public.%I for each statement execute function public.fz_append_only()', t || '_no_truncate', t);
  end loop;
end $$;
drop trigger if exists fz_money_config_append_only on public.fz_money_config;
create trigger fz_money_config_append_only before update or delete on public.fz_money_config for each row execute function public.fz_append_only();

-- ---------------------------------------------------------------------------------------------------------------------------- the office sub-ledgers (views)
-- Office of a row (the same rule as fz_money_stamp(), applied live to rows not stamped yet):
--   ledger      stamp -> the office of the spend reservation it settled -> its venture's office -> group
--   llm_calls   stamp -> its agent's office -> group
--   reservation stamp -> its venture's office -> its actor agent's office -> group
-- Only rows from the cutover on (or stamped by the owner) count; earlier rows are the group's history.
-- available = net allocation + kept result - open reservations, where result = revenue - expenses - AI and kept = the result itself when it is a loss (a loss uses up the
-- allocation; revenue first covers the office's own costs) or reinvest_pct % of it when it is a profit (the rest of the profit belongs to the group). At 0 % an office can
-- never spend more than its allocation net of losses.
-- Row filter: the service path (service_role, postgres / the owner's SQL session, the cron job) sees all; a scoped identity its OWN office (group scope: every office);
-- a dormant / unknown token and ANY other role (even one granted select by mistake) see nothing.
create or replace view public.fz_office_money with (security_barrier = true) as
with cfg as (select cutover_at from public.fz_money_config where id = 1),
led as (
  select coalesce(a.office_id, ra.office_id, v.office_id, 'f0000000-0000-4000-8000-000000000000'::uuid) as office_id, l.kind, l.amount_cents::bigint as cents
    from public.ledger l
    cross join cfg
    left join public.fz_money_attribution a on a.source = 'ledger' and a.source_id = l.id
    left join lateral (select x.office_id from public.spend_reservations sr join public.fz_money_attribution x on x.source = 'reservation' and x.source_id = sr.id
                        where sr.ledger_id = l.id limit 1) ra on true
    left join public.ventures v on v.id = l.venture_id
   where l.status = 'received' and not coalesce(l.intercompany, false) and l.kind in ('revenue', 'expense')
     and (l.created_at >= cfg.cutover_at or a.office_id is not null)
),
ai as (
  select coalesce(a.office_id, g.office_id, 'f0000000-0000-4000-8000-000000000000'::uuid) as office_id, coalesce(c.actual_cents, c.reserved_cents)::bigint as cents
    from public.llm_calls c
    cross join cfg
    left join public.fz_money_attribution a on a.source = 'llm_call' and a.source_id = c.id
    left join public.agents g on g.slug = c.agent_slug
   where c.status in ('reserved', 'done') and (c.started_at >= cfg.cutover_at or a.office_id is not null)
),
res as (
  select coalesce(a.office_id, v.office_id, g.office_id, 'f0000000-0000-4000-8000-000000000000'::uuid) as office_id, r.cents::bigint as cents
    from public.spend_reservations r
    cross join cfg
    left join public.fz_money_attribution a on a.source = 'reservation' and a.source_id = r.id
    left join public.ventures v on v.id = r.venture_id
    left join public.agents g on g.slug = r.actor
   where r.status = 'reserved' and (r.created_at >= cfg.cutover_at or a.office_id is not null)
),
alloc as (
  select office_id, coalesce(sum(cents) filter (where kind = 'allocate'), 0)::bigint as allocated, coalesce(sum(cents) filter (where kind = 'clawback'), 0)::bigint as clawed
    from public.fz_office_allocations group by office_id
),
m as (
  select o.id as office_id, o.slug as office, o.title, o.kind, o.status,
         coalesce(al.allocated, 0) as allocated_cents, coalesce(al.clawed, 0) as clawed_back_cents,
         coalesce((select sum(cents) from led where led.office_id = o.id and led.kind = 'revenue'), 0)::bigint as revenue_cents,
         coalesce((select sum(cents) from led where led.office_id = o.id and led.kind = 'expense'), 0)::bigint as expense_cents,
         coalesce((select sum(cents) from ai where ai.office_id = o.id), 0)::bigint as ai_cents,
         coalesce((select sum(cents) from res where res.office_id = o.id), 0)::bigint as reserved_cents,
         coalesce(p.reinvest_pct, 0) as reinvest_pct
    from public.fz_offices o
    left join alloc al on al.office_id = o.id
    left join public.fz_office_money_policy p on p.office_id = o.id
)
select m.office_id, m.office, m.title, m.kind, m.status, m.allocated_cents, m.clawed_back_cents, m.allocated_cents - m.clawed_back_cents as net_allocation_cents,
       m.revenue_cents, m.expense_cents, m.ai_cents, m.expense_cents + m.ai_cents as spent_cents, m.reserved_cents,
       m.revenue_cents - m.expense_cents - m.ai_cents as profit_cents, m.reinvest_pct,
       case when m.kind = 'office' then
         m.allocated_cents - m.clawed_back_cents - m.reserved_cents
         + case when m.revenue_cents - m.expense_cents - m.ai_cents > 0 then ((m.revenue_cents - m.expense_cents - m.ai_cents) * m.reinvest_pct) / 100
                else m.revenue_cents - m.expense_cents - m.ai_cents end
       end as available_cents,
       (select cutover_at from cfg) as since
  from m
 where coalesce(nullif(current_setting('role', true), ''), 'none') in ('none', 'postgres', 'service_role')      -- review fix 7: an allowlist of who sees everything
    or (coalesce(nullif(current_setting('role', true), ''), 'none') in ('fz_jarvis', 'fz_office_agent', 'fz_auditor')
        and ((select public.is_group_scope()) or m.office_id = (select public.current_office_id())));   -- scoped: own office (group scope: all); anyone else: nothing

-- the allocation history (who gave or took back how much, and why), same row filter
create or replace view public.fz_office_allocation_log with (security_barrier = true) as
select a.id, a.office_id, o.slug as office, a.kind, a.cents, a.reason, a.by, a.proposal_id, a.at
  from public.fz_office_allocations a
  join public.fz_offices o on o.id = a.office_id
 where coalesce(nullif(current_setting('role', true), ''), 'none') in ('none', 'postgres', 'service_role')      -- review fix 7: an allowlist of who sees everything
    or (coalesce(nullif(current_setting('role', true), ''), 'none') in ('fz_jarvis', 'fz_office_agent', 'fz_auditor')
        and ((select public.is_group_scope()) or a.office_id = (select public.current_office_id())));   -- scoped: own office (group scope: all); anyone else: nothing

revoke all on public.fz_office_money, public.fz_office_allocation_log from public, anon, authenticated, service_role, fz_jarvis, fz_office_agent, fz_auditor;
grant select on public.fz_office_money, public.fz_office_allocation_log to service_role, fz_jarvis, fz_office_agent, fz_auditor;

-- ---------------------------------------------------------------------------------------------------------------------------- stamping
-- Stamps rows from the cutover on that have no attribution yet (bounded per call). Reservations first, so a ledger row settled from one inherits its office.
create or replace function public.fz_money_stamp() returns integer
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare c timestamptz; n int := 0; k int; g uuid := 'f0000000-0000-4000-8000-000000000000';
begin
  select cutover_at into c from public.fz_money_config where id = 1;
  if c is null then return 0; end if;
  insert into public.fz_money_attribution (source, source_id, office_id, how)
    select 'reservation', r.id, coalesce(v.office_id, a.office_id, g),
           case when v.office_id is not null then 'venture' when a.office_id is not null then 'agent' else 'group' end
      from public.spend_reservations r
      left join public.ventures v on v.id = r.venture_id
      left join public.agents a on a.slug = r.actor
     where r.created_at >= c and not exists (select 1 from public.fz_money_attribution x where x.source = 'reservation' and x.source_id = r.id)
     order by r.created_at limit 5000
  on conflict do nothing;
  get diagnostics k = row_count; n := n + k;
  insert into public.fz_money_attribution (source, source_id, office_id, how)
    select 'ledger', l.id, coalesce(ra.office_id, v.office_id, g),
           case when ra.office_id is not null then 'reservation' when v.office_id is not null then 'venture' else 'group' end
      from public.ledger l
      left join lateral (select x.office_id from public.spend_reservations sr join public.fz_money_attribution x on x.source = 'reservation' and x.source_id = sr.id
                          where sr.ledger_id = l.id limit 1) ra on true
      left join public.ventures v on v.id = l.venture_id
     where l.created_at >= c and not exists (select 1 from public.fz_money_attribution x where x.source = 'ledger' and x.source_id = l.id)
     order by l.created_at limit 5000
  on conflict do nothing;
  get diagnostics k = row_count; n := n + k;
  insert into public.fz_money_attribution (source, source_id, office_id, how)
    select 'llm_call', l.id, coalesce(a.office_id, g), case when a.office_id is not null then 'agent' else 'group' end
      from public.llm_calls l
      left join public.agents a on a.slug = l.agent_slug
     where l.started_at >= c and not exists (select 1 from public.fz_money_attribution x where x.source = 'llm_call' and x.source_id = l.id)
     order by l.started_at limit 5000
  on conflict do nothing;
  get diagnostics k = row_count; n := n + k;
  return n;
end $$;
revoke all on function public.fz_money_stamp() from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------------------------------------- reads for the owner and the bot
-- one office's available balance (service / owner). Internal helper: the scoped roles read the view instead. Returns a plain number on purpose: a function returning the
-- VIEW's row type cannot be restored from the off-site backup (the restore does not recreate these views; found by the backup drill).
create or replace function public.fz_office_available_cents(p_office uuid) returns bigint
language sql stable security definer set search_path to 'pg_catalog' as $$
  select available_cents from public.fz_office_money where office_id = p_office
$$;
revoke all on function public.fz_office_available_cents(uuid) from public, anon, authenticated;

-- group capital that is not earmarked for an office: the capital controller's available cash minus every office's positive available balance
create or replace function public.fz_unallocated_cents() returns bigint
language sql stable security definer set search_path to 'pg_catalog' as $$
  select coalesce((public.capital_snapshot() ->> 'available_cents')::bigint, 0)
       - coalesce((select sum(greatest(available_cents, 0)) from public.fz_office_money where kind = 'office'), 0)
$$;
revoke all on function public.fz_unallocated_cents() from public, anon, authenticated;

-- the consolidated owner report: per office allocated / spent / revenue / profit / available, group totals, unallocated capital, pending proposals
create or replace function public.fz_money_report() returns jsonb
language plpgsql stable security definer set search_path to 'pg_catalog' as $$
declare s jsonb := public.capital_snapshot();
begin
  return jsonb_build_object(
    'since', (select cutover_at from public.fz_money_config where id = 1),
    'offices', coalesce((select jsonb_agg(jsonb_build_object('office', office, 'title', title, 'status', status, 'allocated_cents', net_allocation_cents,
                          'spent_cents', spent_cents, 'reserved_cents', reserved_cents, 'revenue_cents', revenue_cents, 'profit_cents', profit_cents,
                          'reinvest_pct', reinvest_pct, 'available_cents', available_cents) order by office) from public.fz_office_money where kind = 'office'), '[]'::jsonb),
    'group', (select jsonb_build_object('spent_cents', spent_cents, 'reserved_cents', reserved_cents, 'revenue_cents', revenue_cents, 'profit_cents', profit_cents)
                from public.fz_office_money where kind = 'group'),
    'totals', (select jsonb_build_object('allocated_cents', coalesce(sum(net_allocation_cents) filter (where kind = 'office'), 0),
                                         'spent_cents', coalesce(sum(spent_cents), 0), 'reserved_cents', coalesce(sum(reserved_cents), 0),
                                         'revenue_cents', coalesce(sum(revenue_cents), 0), 'profit_cents', coalesce(sum(profit_cents), 0),
                                         'office_available_cents', coalesce(sum(greatest(available_cents, 0)) filter (where kind = 'office'), 0))
                 from public.fz_office_money),
    'capital_available_cents', (s ->> 'available_cents')::bigint,
    'capital_mode', s ->> 'mode',
    'unallocated_cents', public.fz_unallocated_cents(),
    'pending_proposals', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'office', o.slug, 'kind', p.kind, 'cents', p.cents, 'reinvest_pct', p.reinvest_pct,
                                     'by', p.proposed_by, 'rationale', left(p.rationale, 300), 'expires_at', p.expires_at) order by p.created_at)
                                     from public.fz_office_money_proposals p join public.fz_offices o on o.id = p.office_id
                                    where p.status = 'pending' and p.expires_at > now()), '[]'::jsonb),
    'note', 'Virtual sub-ledgers: one real bank account (the group). Office balances are attribution, not cash. Rows before "since" are the group''s.');
end $$;
revoke all on function public.fz_money_report() from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------------------------------------- owner-only controls
create or replace function public.fz_money_require_owner() returns void
language plpgsql stable security definer set search_path to 'pg_catalog' as $$
begin
  if not coalesce(public.is_app_owner(), false) then raise exception 'owner approval required: this action is refused for the bot' using errcode = '42501'; end if;
end $$;
revoke all on function public.fz_money_require_owner() from public, anon, authenticated;

-- the id of an office (never the group). Returns a plain uuid (no table row type in a signature: restorable from the off-site backup).
create or replace function public.fz_money_office(p_office text) returns uuid
language plpgsql stable security definer set search_path to 'pg_catalog' as $$
declare v uuid;
begin
  select id into v from public.fz_offices where slug = p_office and kind = 'office';
  if v is null then raise exception 'unknown office % (the group itself is not allocated to)', coalesce(p_office, '?'); end if;
  return v;
end $$;
revoke all on function public.fz_money_office(text) from public, anon, authenticated;

-- internal executors (owner checked by every caller and again by the table triggers)
create or replace function public.fz_money_do_allocate(p_office text, p_cents integer, p_reason text, p_proposal uuid) returns jsonb
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare o public.fz_offices; v_free bigint; v_id bigint;
begin
  perform public.fz_money_require_owner();
  select * into o from public.fz_offices where id = public.fz_money_office(p_office);
  if coalesce(p_cents, 0) <= 0 then raise exception 'allocation must be above $0'; end if;
  perform pg_advisory_xact_lock(7333);                                    -- the capital controller's lock: no reservation lands between the check and the allocation
  perform public.fz_money_stamp();
  v_free := public.fz_unallocated_cents();
  if p_cents > v_free then
    raise exception 'Refused: $% is more than the $% of group capital not yet allocated. Allocations never exceed real money (claw back from an office or add funds first).',
      to_char(p_cents / 100.0, 'FM999,999,990.00'), to_char(greatest(v_free, 0) / 100.0, 'FM999,999,990.00');
  end if;
  insert into public.fz_office_allocations (office_id, kind, cents, reason, proposal_id, by) values (o.id, 'allocate', p_cents, btrim(p_reason), p_proposal, 'owner') returning id into v_id;
  insert into public.audit_log (actor, action, target, detail) values ('owner', 'office_allocate', 'fz_offices/' || o.slug, jsonb_build_object('cents', p_cents, 'allocation_id', v_id, 'proposal', p_proposal));
  return jsonb_build_object('office', o.slug, 'allocation_id', v_id, 'kind', 'allocate', 'cents', p_cents, 'available_cents', public.fz_office_available_cents(o.id));
end $$;
revoke all on function public.fz_money_do_allocate(text, integer, text, uuid) from public, anon, authenticated;

create or replace function public.fz_money_do_clawback(p_office text, p_cents integer, p_reason text, p_proposal uuid) returns jsonb
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare o public.fz_offices; v_avail bigint; v_c bigint; v_id bigint;
begin
  perform public.fz_money_require_owner();
  select * into o from public.fz_offices where id = public.fz_money_office(p_office);
  perform pg_advisory_xact_lock(7333);
  perform public.fz_money_stamp();
  v_avail := public.fz_office_available_cents(o.id);
  v_c := coalesce(p_cents, v_avail);                                      -- no amount: everything available
  if v_c is null or v_c <= 0 then raise exception 'Nothing to claw back: % has $% available.', o.title, to_char(greatest(coalesce(v_avail, 0), 0) / 100.0, 'FM999,999,990.00'); end if;
  if v_c > v_avail then
    raise exception 'Refused: % has only $% available (spent or reserved money cannot be clawed back).', o.title, to_char(greatest(v_avail, 0) / 100.0, 'FM999,999,990.00');
  end if;
  insert into public.fz_office_allocations (office_id, kind, cents, reason, proposal_id, by) values (o.id, 'clawback', v_c, btrim(p_reason), p_proposal, 'owner') returning id into v_id;
  insert into public.audit_log (actor, action, target, detail) values ('owner', 'office_clawback', 'fz_offices/' || o.slug, jsonb_build_object('cents', v_c, 'allocation_id', v_id, 'proposal', p_proposal));
  return jsonb_build_object('office', o.slug, 'allocation_id', v_id, 'kind', 'clawback', 'cents', v_c, 'available_cents', public.fz_office_available_cents(o.id));
end $$;
revoke all on function public.fz_money_do_clawback(text, integer, text, uuid) from public, anon, authenticated;

create or replace function public.fz_money_do_reinvest(p_office text, p_pct integer) returns jsonb
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare o public.fz_offices; v_old int;
begin
  perform public.fz_money_require_owner();
  select * into o from public.fz_offices where id = public.fz_money_office(p_office);
  if p_pct is null or p_pct < 0 or p_pct > 100 then raise exception 'reinvestment must be 0 to 100 %%'; end if;
  select reinvest_pct into v_old from public.fz_office_money_policy where office_id = o.id;
  insert into public.fz_office_money_policy (office_id, reinvest_pct, updated_by, updated_at) values (o.id, p_pct, 'owner', now())
  on conflict (office_id) do update set reinvest_pct = excluded.reinvest_pct, updated_by = 'owner', updated_at = now();
  insert into public.audit_log (actor, action, target, detail) values ('owner', 'office_reinvest', 'fz_offices/' || o.slug, jsonb_build_object('pct', p_pct, 'was', coalesce(v_old, 0)));
  return jsonb_build_object('office', o.slug, 'reinvest_pct', p_pct, 'was', coalesce(v_old, 0));
end $$;
revoke all on function public.fz_money_do_reinvest(text, integer) from public, anon, authenticated;

create or replace function public.fz_owner_allocate(p_office text, p_cents integer, p_reason text) returns jsonb
language plpgsql security definer set search_path to 'pg_catalog' as $$
begin
  perform public.fz_money_require_owner();
  return public.fz_money_do_allocate(p_office, p_cents, p_reason, null);
end $$;
revoke all on function public.fz_owner_allocate(text, integer, text) from public, anon, authenticated;

-- p_cents null = claw back everything the office has available
create or replace function public.fz_owner_clawback(p_office text, p_cents integer, p_reason text) returns jsonb
language plpgsql security definer set search_path to 'pg_catalog' as $$
begin
  perform public.fz_money_require_owner();
  return public.fz_money_do_clawback(p_office, p_cents, p_reason, null);
end $$;
revoke all on function public.fz_owner_clawback(text, integer, text) from public, anon, authenticated;

create or replace function public.fz_owner_set_reinvest(p_office text, p_pct integer) returns jsonb
language plpgsql security definer set search_path to 'pg_catalog' as $$
begin
  perform public.fz_money_require_owner();
  return public.fz_money_do_reinvest(p_office, p_pct);
end $$;
revoke all on function public.fz_owner_set_reinvest(text, integer) from public, anon, authenticated;

-- execute (approve) or reject a proposal. Approving re-checks everything against TODAY's numbers; if that fails nothing changes and the proposal stays pending.
create or replace function public.fz_owner_decide_office_proposal(p_id uuid, p_approve boolean, p_note text default null) returns jsonb
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare p public.fz_office_money_proposals; o public.fz_offices; res jsonb;
begin
  perform public.fz_money_require_owner();
  select * into p from public.fz_office_money_proposals where id = p_id for update;
  if not found then raise exception 'unknown proposal %', p_id; end if;
  if p.status <> 'pending' then raise exception 'proposal % is already %', p_id, p.status; end if;
  select * into o from public.fz_offices where id = p.office_id;
  if p.expires_at <= now() then
    update public.fz_office_money_proposals set status = 'expired', decided_at = now(), decided_by = 'owner' where id = p_id;
    return jsonb_build_object('proposal', p_id, 'status', 'expired');
  end if;
  if not coalesce(p_approve, false) then
    update public.fz_office_money_proposals set status = 'rejected', decided_at = now(), decided_by = 'owner', result = jsonb_build_object('note', left(coalesce(p_note, ''), 300)) where id = p_id;
    insert into public.audit_log (actor, action, target, detail) values ('owner', 'office_money_rejected', 'fz_office_money_proposals/' || p_id, jsonb_build_object('office', o.slug, 'kind', p.kind));
    return jsonb_build_object('proposal', p_id, 'status', 'rejected');
  end if;
  res := case p.kind
           when 'allocate' then public.fz_money_do_allocate(o.slug, p.cents, 'proposal by ' || p.proposed_by || ': ' || left(p.rationale, 400), p.id)
           when 'clawback' then public.fz_money_do_clawback(o.slug, p.cents, 'proposal by ' || p.proposed_by || ': ' || left(p.rationale, 400), p.id)
           else public.fz_money_do_reinvest(o.slug, p.reinvest_pct) end;
  update public.fz_office_money_proposals set status = 'executed', decided_at = now(), decided_by = 'owner', result = res where id = p_id;
  return jsonb_build_object('proposal', p_id, 'status', 'executed', 'result', res);
end $$;
revoke all on function public.fz_owner_decide_office_proposal(uuid, boolean, text) from public, anon, authenticated;

-- move a ledger row (e.g. revenue the stamp gave to the group) to an office, or back to the group ('group')
create or replace function public.fz_owner_attribute_ledger(p_ledger uuid, p_office text, p_reason text) returns jsonb
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare v_office uuid; v_was uuid;
begin
  perform public.fz_money_require_owner();
  if not exists (select 1 from public.ledger where id = p_ledger) then raise exception 'unknown ledger row'; end if;
  if coalesce(length(btrim(p_reason)), 0) < 3 then raise exception 'give a reason'; end if;
  select id into v_office from public.fz_offices where slug = p_office;
  if v_office is null then raise exception 'unknown office %', p_office; end if;
  select office_id into v_was from public.fz_money_attribution where source = 'ledger' and source_id = p_ledger;
  insert into public.fz_money_attribution (source, source_id, office_id, how, by) values ('ledger', p_ledger, v_office, 'owner', 'owner')
  on conflict (source, source_id) do update set office_id = excluded.office_id, how = 'owner', by = 'owner', at = now();
  insert into public.audit_log (actor, action, target, detail)
    values ('owner', 'ledger_attribution', 'ledger/' || p_ledger, jsonb_build_object('office', p_office, 'was', v_was, 'reason', left(p_reason, 300)));
  return jsonb_build_object('ledger', p_ledger, 'office', p_office);
end $$;
revoke all on function public.fz_owner_attribute_ledger(uuid, text, text) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------------------------------------- the bot / Jarvis: propose only
create or replace function public.fz_propose_office_money(p_office text, p_kind text, p_cents integer, p_reinvest_pct integer, p_rationale text, p_by text default 'jarvis') returns jsonb
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare o public.fz_offices; v_id uuid; v_by text := left(regexp_replace(coalesce(nullif(btrim(p_by), ''), 'jarvis'), '[^A-Za-z0-9:_.-]', '', 'g'), 60); v_what text; v_note text;
begin
  if v_by = '' then v_by := 'jarvis'; end if;
  if coalesce(nullif(current_setting('role', true), ''), 'none') in ('fz_jarvis', 'fz_office_agent', 'fz_auditor') then
    raise exception 'money proposals are made on the service path' using errcode = '42501';
  end if;
  select * into o from public.fz_offices where id = public.fz_money_office(p_office);
  if v_by ilike 'owner%' then v_by := 'bot:' || v_by; end if;                -- a caller cannot record itself as the owner
  perform pg_advisory_xact_lock(hashtext('fzm_prop:' || o.id::text));     -- review fix 8: two concurrent proposals cannot both pass the pending count
  update public.fz_office_money_proposals set status = 'expired', decided_at = now(), decided_by = 'expiry' where status = 'pending' and expires_at <= now();
  if (select count(*) from public.fz_office_money_proposals where office_id = o.id and status = 'pending') >= 3 then
    raise exception '% already has 3 pending money proposals: wait for the owner', o.title;
  end if;
  insert into public.fz_office_money_proposals (office_id, kind, cents, reinvest_pct, rationale, proposed_by)
    values (o.id, p_kind, case when p_kind = 'reinvest' then null else p_cents end, case when p_kind = 'reinvest' then p_reinvest_pct else null end, btrim(p_rationale), v_by)
    returning id into v_id;
  v_what := case p_kind when 'allocate' then format('allocate $%s to %s', to_char(p_cents / 100.0, 'FM999,999,990.00'), o.title)
                        when 'clawback' then format('claw back $%s from %s', to_char(p_cents / 100.0, 'FM999,999,990.00'), o.title)
                        else format('set %s reinvestment to %s%% of profit', o.title, p_reinvest_pct) end;
  -- review fix 6: the real command comes FIRST; the bot's text is fenced below it as an unverified note, with semicolons, quotes and SQL words removed, so it cannot
  -- pass for a command to paste
  v_note := regexp_replace(left(btrim(p_rationale), 600), '[;`''"\\$]', '', 'g');
  v_note := regexp_replace(regexp_replace(v_note, '[[:cntrl:]]+', ' ', 'g'), '-{2,}', '-', 'g');   -- second review: one line, no dash runs: the note cannot fake a fence
  v_note := regexp_replace(v_note, '(fz_[A-Za-z0-9_]*|\m(select|insert|update|delete|drop|grant|revoke|alter|create|truncate|begin|commit|rollback|set_config|execute|call|do)\M)', '[removed]', 'gi');
  if exists (select 1 from public.agents where slug = 'jarvis') then
    insert into public.owner_messages (from_agent, kind, channel, body)
      values ('jarvis', 'money', 'telegram', format(E'Money proposal: %s (proposed by %s).\nTo approve, in your owner session (only you can): select public.fz_owner_decide_office_proposal(%L, true);   false instead of true rejects it.\n----- Jarvis''s note (unverified, not a command) -----\n%s\n----- end of note -----',
                                                    v_what, v_by, v_id, v_note));
  end if;
  insert into public.audit_log (actor, action, target, detail) values (v_by, 'office_money_proposed', 'fz_office_money_proposals/' || v_id, jsonb_build_object('office', o.slug, 'kind', p_kind));
  return jsonb_build_object('proposal', v_id, 'office', o.slug, 'kind', p_kind, 'status', 'pending', 'note', 'Only the owner can execute it.');
end $$;
revoke all on function public.fz_propose_office_money(text, text, integer, integer, text, text) from public, anon, authenticated;


-- ---------------------------------------------------------------------------------------------------------------------------- the office spend gate
-- In FRONT of the unchanged reserve_spend(). Office 'group' (or null): reserve_spend() exactly, the reservation stamped to the group. An office:
--   refused (logged) when the office is not active or its available balance is below the cost; otherwise reserve_spend() decides, unchanged, and an allowed
--   reservation is stamped to the office (so its spend and, once settled, its ledger row count against the office). It can only refuse, never allow more.
-- Service path only. A scoped identity is refused before anything is evaluated: it can never consume an owner approval or create a reservation.
create or replace function public.fz_reserve_office_spend(p_office text, p_actor text, p_action text, p_vendor text, p_purpose text, p_expected_benefit text,
                                                          p_alternatives text, p_cents integer, p_recurring boolean default false, p_monthly_cents integer default null,
                                                          p_days_to_benefit integer default null, p_venture uuid default null, p_mission uuid default null) returns jsonb
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare o public.fz_offices; v_avail bigint; v_reason text; res jsonb; v_cents int := coalesce(p_cents, 0); v_found boolean;
begin
  if coalesce(nullif(current_setting('role', true), ''), 'none') in ('fz_jarvis', 'fz_office_agent', 'fz_auditor') then
    raise exception 'the office spend gate is service-path only: a scoped identity evaluates with fz_authorize_action and never reserves' using errcode = '42501';
  end if;
  -- review fix 2: when the spend is for a venture, the VENTURE decides the office (M1 ventures.office_id); a different p_office is refused, and 'group' is accepted
  -- only for a venture of the group. So nobody can skip a dormant office by saying 'group', or charge one office for another office's venture.
  if p_venture is not null then
    select f.* into o from public.ventures v join public.fz_offices f on f.id = v.office_id where v.id = p_venture;
    v_found := found;
    if not v_found then
      v_reason := 'The venture or its office is unknown: refused.';
    elsif p_office is not null and p_office is distinct from o.slug then
      v_reason := format('Office mismatch: this venture belongs to %s, not %s. Refused.', o.slug, p_office);
    end if;
  elsif p_office is null or p_office = 'group' then
    select * into o from public.fz_offices where kind = 'group';
  else
    select * into o from public.fz_offices where slug = p_office and kind = 'office';
    if not found then raise exception 'unknown office %', p_office; end if;
  end if;
  if v_reason is null and o.kind = 'office' then
    perform pg_advisory_xact_lock(7333);                                  -- reserve_spend's lock, then authorize_action's: the same order they take them (no deadlock)
    perform pg_advisory_xact_lock(7332);
    -- review fix 1: M1's office layer, exactly as fz_authorize_action applies it (status, office rule allowed / per-action cap / daily count)
    v_reason := public.fz_office_refusal(o.id, p_action, v_cents);
    if v_reason is null then
      v_avail := public.fz_office_available_cents(o.id);
      if v_cents > 0 and coalesce(v_avail, 0) < v_cents then
        v_reason := format('Office %s has $%s available, the cost is $%s. Ask the owner for an allocation (fz_propose_office_money).', o.title,
                           to_char(greatest(coalesce(v_avail, 0), 0) / 100.0, 'FM999,999,990.00'), to_char(v_cents / 100.0, 'FM999,999,990.00'));
      end if;
    end if;
  end if;
  if v_reason is not null then
    insert into public.action_log (actor, action, tier, decision, reason, cents, venture_id, mission_id, ref, detail)
      values (coalesce(nullif(btrim(p_actor), ''), 'unknown'), p_action, (select tier from public.action_policy where action = p_action), 'deny', v_reason, greatest(v_cents, 0),
              p_venture, p_mission, p_vendor, jsonb_build_object('office', coalesce(o.slug, p_office), 'layer', 'office_money', 'available_cents', v_avail));
    return jsonb_build_object('decision', 'deny', 'reason', v_reason, 'office', coalesce(o.slug, p_office), 'available_cents', v_avail);
  end if;
  res := public.reserve_spend(p_actor, p_action, p_vendor, p_purpose, p_expected_benefit, p_alternatives, p_cents, p_recurring, p_monthly_cents, p_days_to_benefit, p_venture, p_mission);
  if res ->> 'decision' = 'allow' and res ? 'reservation_id' then
    -- stamp the reservation to the office and label the allow row reserve_spend() wrote (its action_log_id) with detail.office, so M1's office daily count counts it.
    -- Inline on purpose (second review N1): a separate definer helper would be callable by the service key (the lockdown grants it every function) and could stamp any
    -- reservation to any office or poison the office counts.
    insert into public.fz_money_attribution (source, source_id, office_id, how, by) values ('reservation', (res ->> 'reservation_id')::uuid, o.id, 'office_gate', left(coalesce(p_actor, ''), 60))
    on conflict do nothing;
    update public.action_log l set detail = coalesce(l.detail, '{}'::jsonb) || jsonb_build_object('office', o.slug, 'layer', 'office_gate')
     where l.id = (select r.action_log_id from public.spend_reservations r where r.id = (res ->> 'reservation_id')::uuid) and l.decision = 'allow';
  end if;
  return res || jsonb_build_object('office', o.slug);
end $$;
revoke all on function public.fz_reserve_office_spend(text, text, text, text, text, text, text, integer, boolean, integer, integer, uuid, uuid) from public, anon, authenticated;

-- none of the functions above is for a scoped identity (the M1 allowlist stays exact)
do $$
declare f regprocedure;
begin
  for f in select p.oid::regprocedure from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in
             ('fz_money_owner_only', 'fz_money_proposal_guard', 'fz_money_attribution_guard', 'fz_money_stamp', 'fz_office_available_cents', 'fz_unallocated_cents', 'fz_money_report',
              'fz_money_require_owner', 'fz_money_office', 'fz_money_do_allocate', 'fz_money_do_clawback', 'fz_money_do_reinvest', 'fz_owner_allocate', 'fz_owner_clawback',
              'fz_owner_set_reinvest', 'fz_owner_decide_office_proposal', 'fz_owner_attribute_ledger', 'fz_propose_office_money', 'fz_reserve_office_spend') loop
    execute format('revoke all on function %s from fz_jarvis, fz_office_agent, fz_auditor', f);
  end loop;
end $$;

-- stamp every 15 minutes (on Supabase: pg_cron). Also run by the gate and by every owner money action.
do $$
begin
  if exists (select 1 from pg_namespace where nspname = 'cron') then
    perform cron.unschedule(jobid) from cron.job where jobname = 'fz-money-stamp';
    perform cron.schedule('fz-money-stamp', '*/15 * * * *', 'select public.fz_money_stamp()');
  end if;
end $$;

-- ---------------------------------------------------------------------------------------------------------------------------- table registry (M1) for the new tables
-- office-owned money (by office_id): NO scoped access to the raw tables; scoped identities read the two filtered views. Group config: no scoped access.
insert into public.fz_table_registry (relname, scope, scope_column, data_class, fz_read, fz_write, fz_insert_columns, fz_update_columns, note) values
  ('fz_money_config',           'group',  null,        'confidential', false, '{}', null, null, 'office money: attribution cutover (rows before it are the group''s)'),
  ('fz_office_allocations',     'office', 'office_id', 'confidential', false, '{}', null, null, 'office money: owner allocations / clawbacks (append-only, owner-only writes); read through fz_office_allocation_log'),
  ('fz_office_money_policy',    'office', 'office_id', 'confidential', false, '{}', null, null, 'office money: reinvestment rule per office (owner-only; no row = 0 %)'),
  ('fz_office_money_proposals', 'office', 'office_id', 'confidential', false, '{}', null, null, 'office money: bot / Jarvis proposals; only the owner executes'),
  ('fz_money_attribution',      'office', 'office_id', 'confidential', false, '{}', null, null, 'office money: which office each ledger row / model call / reservation belongs to (stamped once, owner re-attributes)')
on conflict (relname) do update set scope = excluded.scope, scope_column = excluded.scope_column, data_class = excluded.data_class, fz_read = excluded.fz_read,
  fz_write = excluded.fz_write, fz_insert_columns = excluded.fz_insert_columns, fz_update_columns = excluded.fz_update_columns, note = excluded.note;

-- ---------------------------------------------------------------------------------------------------------------------------- backup classification (PROTECTED: owner approval)
-- Same rows as 20261127_org_access_v1 (unchanged, same order) plus the five office-money tables. Without this the backup fails closed on unclassified tables.
create or replace function public.backup_classification() returns table (table_name text, data_class text, note text)
language sql immutable set search_path to 'pg_catalog' as $$
  select * from (values
    -- public: non-personal reference data
    ('model_prices', 'public', 'published model prices'),
    -- secret: never exported, never in any backup
    ('push_config', 'secret', 'private push keys'),
    ('push_subscriptions', 'secret', 'push endpoints and keys'),
    -- client_pii: third-party personal data (leads, prospects, replies, setters, suppression list). EXCLUDED until retention, access, deletion and key policy are set.
    ('leads', 'client_pii', 'prospect name, phone, email, notes'),
    ('outbox', 'client_pii', 'drafts and recipients (to_ref) for leads'),
    ('lead_replies', 'client_pii', 'free-text notes about replies from leads'),
    ('deals', 'client_pii', 'notes about leads; references leads'),
    ('contact_suppressions', 'client_pii', 'opted-out email addresses. After a restore from an off-site backup this list is EMPTY: restore it from the database provider backup before any outreach is ever enabled'),
    ('setters', 'client_pii', 'sales partner name and contact'),
    ('setter_events', 'client_pii', 'client names per setter event'),
    ('setter_payouts', 'client_pii', 'references setters'),
    ('client_workspaces', 'client_pii', 'client company names'),
    -- internal: operating data of the owner and the ventures
    ('account_requests', 'internal', 'vendor sign-up requests; login name only, never a password'),
    ('accounts_registry', 'internal', 'which service accounts exist; vault reference only'),
    ('action_log', 'internal', 'action audit'), ('action_policy', 'internal', 'autonomy tiers'), ('agent_runs', 'internal', 'run summaries (free text)'),
    ('agents', 'internal', 'agent definitions'), ('alert_state', 'internal', 'alert throttling'), ('app_owners', 'internal', 'owner login emails'),
    ('approval_requests', 'internal', 'approvals'), ('audit_log', 'internal', 'audit trail (free text in detail)'), ('bank_accounts', 'internal', 'owner own bank labels and last4'),
    ('bank_balances', 'internal', 'owner own balances'), ('bank_transactions', 'internal', 'owner own transactions'), ('build_requests', 'internal', 'build queue'),
    ('capital_policy', 'internal', 'spend limits'), ('company_profile', 'internal', 'sender identity of the owner ventures'), ('dayjob_days', 'internal', 'day job counters'),
    ('dayjob_targets', 'internal', 'day job targets'), ('departments', 'internal', 'org'), ('escalations', 'internal', 'escalations (free text)'),
    ('evidence_sources', 'internal', 'fetched public web pages'), ('executor_registry', 'internal', 'executor limits'), ('executor_runs', 'internal', 'executor audit'),
    ('handbook', 'internal', 'handbook'), ('human_handoffs', 'internal', 'tasks for the owner (free text)'), ('ideas', 'internal', 'ideas'),
    ('integration_status', 'internal', 'integration health'), ('ledger', 'internal', 'books'), ('llm_calls', 'internal', 'model call meter'),
    ('memory', 'internal', 'agent memory (free text)'), ('mission_outcomes', 'internal', 'outcomes'), ('missions', 'internal', 'missions (free text)'),
    ('org_changes', 'internal', 'org proposals'), ('owner_messages', 'internal', 'messages to the owner (free text)'), ('payment_instructions', 'internal', 'payment requests; payee may be a person'),
    ('predictions', 'internal', 'predictions'), ('reconciliation_flags', 'internal', 'reconciliation'), ('setter_terms', 'internal', 'setter commission terms'),
    ('spend_reservations', 'internal', 'spend gateway'), ('system_state', 'internal', 'kill switch and modes'), ('systems', 'internal', 'registered systems'),
    ('tasks', 'internal', 'tasks (free text)'), ('tool_registry', 'internal', 'tools'), ('venture_assets', 'internal', 'assets'), ('venture_config', 'internal', 'venture offer config'),
    ('venture_goals', 'internal', 'goals'), ('venture_procedures', 'internal', 'procedures'), ('ventures', 'internal', 'ventures'), ('waterfall_policy', 'internal', 'money waterfall'),
    ('web_messages', 'internal', 'owner chat (free text)'),
    -- Jarvis core v2 (20261123). Class 'secret' = NOT in the off-site export (the database provider's own backups still hold them). Reason: the leak-redaction
    -- export needs a reviewed backup_redaction_spec() entry for every exported text column; until those are written (follow-up, protected) the safe choice is to keep
    -- these operational tables out of the off-site file. They hold no client data by design; jarvis_result_cache may.
    ('jarvis_core_config', 'secret', 'Jarvis core switches; off-site export pending a reviewed redaction spec'), ('jarvis_jobs', 'secret', 'job queue; off-site export pending a reviewed redaction spec'),
    ('jarvis_job_events', 'secret', 'append-only queue audit; off-site export pending a reviewed redaction spec'), ('jarvis_task_stats', 'secret', 'run counts per task class; off-site export pending'),
    ('jarvis_changelog', 'secret', 'append-only changelog; off-site export pending'), ('jarvis_call_log', 'secret', 'append-only emergency-call ledger (no phone numbers); off-site export pending'),
    ('jarvis_large_approvals', 'secret', 'owner approvals for the large model tier; off-site export pending'), ('jarvis_self_fund_credits', 'secret', 'owner-confirmed Jarvis revenue (amounts only); off-site export pending'),
    ('jarvis_agent_wakes', 'secret', 'append-only agent wake / sleep log; off-site export pending'),
    ('jarvis_result_cache', 'secret', 'cached task output; may contain client data, never exported (rebuilt on demand)'),
    ('jarvis_call_criteria', 'secret', 'the owner-approved emergency-call events (copy of ops/CRITICAL_EVENTS.json); off-site export pending'),
    ('jarvis_seed_staging', 'secret', 'owner profile import staged by the bot until the owner applies it; private, never exported'),
    -- Jarvis hands v1 (20261124): metadata only, no secrets (vault references are ids; tokens and passwords live only in the vault)
    ('hand_connectors', 'internal', 'connector registry and owner settings'), ('hand_accounts', 'internal', 'which accounts exist; vault references only, no secrets'),
    ('hand_actions', 'internal', 'action and content queue (payload free text is not exported)'), ('hand_standing', 'internal', 'owner standing approvals'),
    -- Org & Access M1 (20261127): org registry. Class 'secret' = not in the off-site export (as Jarvis core): the offices, identities and table registry are re-seeded by the
    -- migration (statuses come back DORMANT, which is the safe state); exporting them needs reviewed backup_redaction_spec() rows first (follow-up, protected).
    ('fz_offices', 'secret', 'the group and the eight offices; re-seeded by the migration; off-site export pending a reviewed redaction spec'),
    ('fz_identities', 'secret', 'identity registry (status, pinned token ids); re-seeded by the migration'),
    ('fz_table_registry', 'secret', 'table classification; re-seeded by the migration'),
    ('fz_workspace_offices', 'secret', 'which office serves each client workspace; off-site export pending'),
    ('fz_office_action_policy', 'secret', 'per-office tighten-only permission overlay; off-site export pending'),
    ('fz_org_archive', 'secret', 'append-only log of the org re-seed decisions; off-site export pending'),
    -- Office money M2 (20261128): virtual sub-ledgers. 'secret' = not in the off-site export, like the M1 registry. After a restore from the off-site file every office is
    -- back at $0 with no reinvestment (the strictest state); the database provider's own backups keep the history. Exporting needs reviewed redaction-spec rows (protected).
    ('fz_money_config', 'secret', 'office money attribution cutover; re-created by the migration'),
    ('fz_office_allocations', 'secret', 'owner allocations / clawbacks per office (amounts and reasons); off-site export pending'),
    ('fz_office_money_policy', 'secret', 'per-office reinvestment rule; off-site export pending'),
    ('fz_office_money_proposals', 'secret', 'bot money proposals and owner decisions; off-site export pending'),
    ('fz_money_attribution', 'secret', 'office of each ledger row / model call / reservation; off-site export pending')
  ) v (table_name, data_class, note)
$$;
revoke all on function public.backup_classification() from public, anon, authenticated;
reset lock_timeout;

-- ===== 20261129_approvals_kernel_v1.sql =====
-- FENDEZY GROUP Phase 1, milestone M3 "Approvals kernel + office wiring". ADDITIVE. Needs 20261127_org_access_v1 (M1) and 20261128_office_money_v1 (M2).
-- Design (docs/architecture/PHASE1_M3_APPROVALS.md):
--   * fz_approval_queue (view): ONE read model of everything waiting on the owner: the existing approval_requests (red / approve-first actions) and the M2 office money
--     proposals. Type, office, requester, action, amount, risk, created, expires, effective status, and HOW it is decided. Metadata only (no recommendation text).
--     Scoped office identities read their own office's rows; Jarvis and the auditor read all; anon / authenticated nothing (M1 helpers only: the scoped allowlist is unchanged).
--   * Decisions keep their EXISTING owner-verified paths, unchanged: approval_requests by the owner's Telegram tap (owner_messages -> hq_commands.apply_decision ->
--     hq_policy.decide_approval, consumed once by authorize_action); money proposals by fz_owner_decide_office_proposal (signed-in owner only). No new approval route.
--   * fz_queue_expire(): one expiry rule for both (pending past expires_at -> expired) and a cap of p_cap (5) pending action approvals per office per action (the oldest
--     extras are superseded -> expired); money proposals are already capped at insert (M2: 3 pending per office). Every state change it makes, and every status change of a money proposal (trigger on the M2 table), writes an audit_log row. Nothing is deleted.
--     Expired is the safe state: authorize_action never consumes an expired or pending request, and decide_approval only changes pending ones.
--   * fz_prepare_office_payment(): the office layer in front of the UNCHANGED prepare_payment() (the one paid path that carries a venture). It can only refuse (the
--     venture's office is not active, or its available balance is short); otherwise it returns exactly what prepare_payment() decides. Service path only. The bot uses it
--     only when FZ_OFFICE_SPEND_GATE=1 (hq_payments.py); default OFF = today's behaviour.
--   No change to authorize_action, action_policy, approval_requests' structure or triggers, caps, kill switch, mode, executors, hq_llm or any owner-identity check. No new table.
-- Ordered BEFORE the lockdown (R3). Rollback: ops/rollback_approvals_kernel.sql (before ops/rollback_office_money.sql). Safe to re-run.

set lock_timeout = '5s';

-- ---------------------------------------------------------------------------------------------------------------------------- the queue (read model)
create or replace view public.fz_approval_queue with (security_barrier = true) as
with q as (
  select 'action_approval'::text as request_type, r.id as source_id,
         coalesce(g.office_id, 'f0000000-0000-4000-8000-000000000000'::uuid) as office_id,
         r.actor as requester, r.action, r.cents::bigint as amount_cents, coalesce(p.tier, 'unknown') as risk,
         case when r.status = 'pending' and r.expires_at <= now() then 'expired' else r.status end as status,
         r.created_at, r.expires_at, r.decided_at,
         'owner Telegram tap (approval message)'::text as decided_by_path
    from public.approval_requests r
    left join public.agents g on g.slug = r.actor
    left join public.action_policy p on p.action = r.action
  union all
  -- every column named in both branches: the off-site restore re-creates the view from pg_get_viewdef(), which is only a fixed point with named columns
  select 'office_money_' || m.kind as request_type, m.id as source_id, m.office_id as office_id, m.proposed_by as requester, m.kind as action,
         m.cents::bigint as amount_cents, 'money'::text as risk,
         case when m.status = 'pending' and m.expires_at <= now() then 'expired' else m.status end as status,
         m.created_at as created_at, m.expires_at as expires_at, m.decided_at as decided_at,
         'owner session: fz_owner_decide_office_proposal'::text as decided_by_path
    from public.fz_office_money_proposals m
)
select q.request_type, q.source_id, q.office_id, o.slug as office, q.requester, q.action, q.amount_cents, q.risk, q.status, q.created_at, q.expires_at, q.decided_at,
       q.decided_by_path
  from q
  left join public.fz_offices o on o.id = q.office_id
 where coalesce(nullif(current_setting('role', true), ''), 'none') in ('none', 'postgres', 'service_role')      -- review fix 7: an allowlist of who sees everything
    or (coalesce(nullif(current_setting('role', true), ''), 'none') in ('fz_jarvis', 'fz_office_agent', 'fz_auditor')
        and ((select public.is_group_scope()) or q.office_id = (select public.current_office_id())));   -- scoped: own office (group scope: all); anyone else: nothing

revoke all on public.fz_approval_queue from public, anon, authenticated, service_role, fz_jarvis, fz_office_agent, fz_auditor;
grant select on public.fz_approval_queue to service_role, fz_jarvis, fz_office_agent, fz_auditor;

-- ---------------------------------------------------------------------------------------------------------------------------- expiry + cap (one rule for every type)
-- p_cap: pending requests allowed per office per type (action_approval: per action too), honoured only for the owner / the database session (default 5).
-- Returns how many it expired. Service path and cron only.
create or replace function public.fz_queue_expire(p_cap integer default 5) returns integer
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare n int := 0; r record; v_role text := coalesce(nullif(current_setting('role', true), ''), 'none'); v_cap int := 5;
begin
  if v_role in ('fz_jarvis', 'fz_office_agent', 'fz_auditor') then
    raise exception 'the approval queue is maintained on the service path only' using errcode = '42501';
  end if;
  -- review fix 4: the cap is 5. Only the signed-in owner or the database's own session (the cron job / the owner's SQL session: no API role) may choose another one;
  -- the bot's key (service_role) cannot mass-expire requests with a small cap.
  if p_cap is not null and (coalesce(public.is_app_owner(), false) or v_role in ('none', 'postgres')) then v_cap := greatest(p_cap, 1); end if;
  -- 1. past expiry
  for r in update public.approval_requests set status = 'expired' where status = 'pending' and expires_at <= now() returning id, actor, action, cents loop
    insert into public.audit_log (actor, action, target, detail) values ('queue', 'approval_expired', 'approval_requests/' || r.id,
      jsonb_build_object('from', 'pending', 'to', 'expired', 'reason', 'past expiry', 'action', r.action, 'requester', r.actor, 'cents', r.cents));
    n := n + 1;
  end loop;
  for r in update public.fz_office_money_proposals set status = 'expired', decided_at = now(), decided_by = 'expiry' where status = 'pending' and expires_at <= now() returning id loop
    n := n + 1;                                                           -- audited by the proposal status trigger
  end loop;
  -- 2. cap: at most v_cap pending per office per type (the newest are kept; the older extras are superseded)
  for r in update public.approval_requests a set status = 'expired' from (
             select x.id from (select r2.id, row_number() over (partition by coalesce(g.office_id, 'f0000000-0000-4000-8000-000000000000'::uuid), r2.action order by r2.created_at desc, r2.id) k
                                 from public.approval_requests r2 left join public.agents g on g.slug = r2.actor where r2.status = 'pending') x where x.k > v_cap) s
           where a.id = s.id and a.status = 'pending' returning a.id, a.actor, a.action, a.cents loop
    insert into public.audit_log (actor, action, target, detail) values ('queue', 'approval_expired', 'approval_requests/' || r.id,
      jsonb_build_object('from', 'pending', 'to', 'expired', 'reason', format('superseded: more than %s pending for this office and action', v_cap), 'action', r.action, 'requester', r.actor, 'cents', r.cents));
    n := n + 1;
  end loop;
  -- money proposals are capped at insert (M2: 3 pending per office), so nothing to supersede there
  return n;
end $$;
revoke all on function public.fz_queue_expire(integer) from public, anon, authenticated;

-- every status change of a money proposal is audited (M2 audits proposals and executions; this covers rejected / expired / executed uniformly)
create or replace function public.fz_queue_audit_proposal() returns trigger
language plpgsql security definer set search_path to 'pg_catalog' as $$
begin
  -- review fix 5: exactly one audit row per change. A rejection is already audited by fz_owner_decide_office_proposal (M2, 'office_money_rejected'), so it is skipped here.
  if new.status is distinct from old.status and new.status <> 'rejected' then
    insert into public.audit_log (actor, action, target, detail) values (coalesce(new.decided_by, 'unknown'), 'office_money_' || new.status, 'fz_office_money_proposals/' || new.id,
      jsonb_build_object('from', old.status, 'to', new.status, 'kind', new.kind, 'office_id', new.office_id, 'cents', new.cents, 'reinvest_pct', new.reinvest_pct));
  end if;
  return null;
end $$;
revoke all on function public.fz_queue_audit_proposal() from public, anon, authenticated;
drop trigger if exists fz_office_money_proposals_audit on public.fz_office_money_proposals;
create trigger fz_office_money_proposals_audit after update on public.fz_office_money_proposals for each row execute function public.fz_queue_audit_proposal();

-- ---------------------------------------------------------------------------------------------------------------------------- office wiring: payments
-- In FRONT of the unchanged prepare_payment(). The office is the venture's office (M1 ventures.office_id). Group (or no venture): prepare_payment() exactly.
create or replace function public.fz_prepare_office_payment(p_actor text, p_payee text, p_cents integer, p_purpose text, p_alternatives text,
                                                            p_due date default null, p_venture_slug text default null) returns jsonb
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare o public.fz_offices; v_avail bigint; v_reason text; v_cents int := coalesce(p_cents, 0); res jsonb; v_res uuid;
begin
  if coalesce(nullif(current_setting('role', true), ''), 'none') in ('fz_jarvis', 'fz_office_agent', 'fz_auditor') then
    raise exception 'the office payment gate is service-path only' using errcode = '42501';
  end if;
  if p_venture_slug is not null then
    select f.* into o from public.ventures v join public.fz_offices f on f.id = v.office_id where v.slug = p_venture_slug and f.kind = 'office';
  end if;
  if o.id is not null then
    perform pg_advisory_xact_lock(7333);                                  -- reserve_spend's lock, then authorize_action's: their order (no deadlock)
    perform pg_advisory_xact_lock(7332);
    -- review fix 1: M1's office layer exactly as fz_authorize_action applies it (status, office rule allowed / per-action cap / daily count)
    v_reason := public.fz_office_refusal(o.id, 'payment_instruction', v_cents);
    if v_reason is null then
      v_avail := public.fz_office_available_cents(o.id);
      if v_cents > 0 and coalesce(v_avail, 0) < v_cents then
        v_reason := format('Office %s has $%s available, the payment is $%s. Ask the owner for an allocation.', o.title,
                           to_char(greatest(coalesce(v_avail, 0), 0) / 100.0, 'FM999,999,990.00'), to_char(v_cents / 100.0, 'FM999,999,990.00'));
      end if;
    end if;
    if v_reason is not null then
      insert into public.action_log (actor, action, tier, decision, reason, cents, ref, detail)
        values (coalesce(nullif(btrim(p_actor), ''), 'unknown'), 'payment_instruction', (select tier from public.action_policy where action = 'payment_instruction'), 'deny', v_reason,
                greatest(v_cents, 0), p_payee, jsonb_build_object('office', o.slug, 'layer', 'office_money', 'venture', p_venture_slug, 'available_cents', v_avail));
      return jsonb_build_object('decision', 'deny', 'reason', v_reason, 'office', o.slug, 'available_cents', v_avail);
    end if;
  end if;
  res := public.prepare_payment(p_actor, p_payee, p_cents, p_purpose, p_alternatives, p_due, p_venture_slug);
  if o.id is not null and res ->> 'decision' = 'allow' then                -- stamp the reservation to the office and label its allow row (the office daily count counts it)
    -- inline (second review N1: no separately callable definer helper)
    select reservation_id into v_res from public.payment_instructions where id = (res ->> 'instruction_id')::uuid;
    insert into public.fz_money_attribution (source, source_id, office_id, how, by) values ('reservation', v_res, o.id, 'office_gate', left(coalesce(p_actor, ''), 60)) on conflict do nothing;
    update public.action_log l set detail = coalesce(l.detail, '{}'::jsonb) || jsonb_build_object('office', o.slug, 'layer', 'office_gate')
     where l.id = (select r.action_log_id from public.spend_reservations r where r.id = v_res) and l.decision = 'allow';
  end if;
  return res || jsonb_build_object('office', coalesce(o.slug, 'group'));
end $$;
revoke all on function public.fz_prepare_office_payment(text, text, integer, text, text, date, text) from public, anon, authenticated;

do $$
declare f regprocedure;
begin
  for f in select p.oid::regprocedure from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in ('fz_queue_expire', 'fz_queue_audit_proposal', 'fz_prepare_office_payment') loop
    execute format('revoke all on function %s from fz_jarvis, fz_office_agent, fz_auditor', f);
  end loop;
  if exists (select 1 from pg_namespace where nspname = 'cron') then
    perform cron.unschedule(jobid) from cron.job where jobname = 'fz-queue-expire';
    perform cron.schedule('fz-queue-expire', '*/15 * * * *', 'select public.fz_queue_expire()');
  end if;
end $$;
reset lock_timeout;

-- ===== 20261130_security_hardening_v1.sql =====
-- FENDEZY GROUP Phase 1, milestone M4 "Audit and security hardening". ADDITIVE. Needs M1 (20261127), M2 (20261128), M3 (20261129).
-- Design (docs/architecture/PHASE1_M4_SECURITY.md). Second review (Nov 21) rebuilt the chain and the watch:
--   * fz_audit_chain: a tamper-EVIDENT hash chain over audit_log, strictly in id order, IGNORING audit_log.at (which the service key could forge). Each visible row is first
--     OBSERVED (its hash stored in fz_audit_pending with OUR timestamp); it is chained 5 minutes after it was first seen, with the hash seen then. So a row edited, re-dated or
--     deleted after it was first seen is detected even before it is chained. A hole in the ids becomes a 'gap' link once a later id has been visible 5 minutes (a deleted row, or
--     a rolled-back insert: both are reported, as 'gap', distinct from a 'deleted' chained row). A row that later appears in a gap ('gap_filled') or below the first chained id
--     ('below_genesis') is reported. audit_log itself and its triggers are NOT modified (the real fix, append-only audit_log and ledger, is the owner proposal
--     ops/proposals/audit_ledger_append_only.sql).
--   * fz_audit_verify(): incremental from a stored checkpoint; a full rescan at most nightly, and only for the cron job / the owner (never on demand by the service key).
--   * privileged items in EVERY non-system schema, compared with a committed, reviewed allowlist (fz_expected_grants(), generated into ops/expected_grants.tsv). Standing
--     findings (any anon / authenticated write; service_role UPDATE / DELETE / TRUNCATE on audit_log or ledger) are always reported and can never be acknowledged.
--   * the watch: an item that disappears is marked revoked (its acknowledgement ends), so its return alerts again; SECURITY DEFINER functions the API roles can execute are
--     fingerprinted (body + settings): a change alerts. Alerts have a stable dedupe key; writing them is inline in the watch (no callable alert helper).
--   * rollback + re-apply: the chain, its state, the baseline and the fingerprints are seeded back from fz_archive and the owner is told ("re-initialised").
--   No change to audit_log, ledger, authorize_action, action_policy, caps, kill switch, mode, executors, hq_llm or any owner-identity check. Money controls unchanged (fingerprint).
-- Ordered BEFORE the lockdown (R3). Rollback: ops/rollback_security_hardening.sql (archives the tables, never drops them). Safe to re-run.

set lock_timeout = '5s';

-- ---------------------------------------------------------------------------------------------------------------------------- tables
create table if not exists public.fz_audit_chain (
  seq bigint generated always as identity primary key,
  audit_id bigint not null unique,                                       -- audit_log.id (no foreign key: audit_log is never touched)
  kind text not null default 'row' check (kind in ('row', 'gap')),
  row_hash text not null,                                                -- for a gap: 'gap'
  chain_hash text not null,
  chained_at timestamptz not null default now()
);
create table if not exists public.fz_audit_pending (                    -- rows seen but not chained yet: hash as first seen, and when (our clock, not audit_log.at)
  audit_id bigint primary key,
  row_hash text not null,
  first_seen timestamptz not null default now()
);
create table if not exists public.fz_audit_state (
  id int primary key default 1 check (id = 1),
  genesis_id bigint,
  checkpoint_seq bigint,
  checkpoint_hash text,
  last_full_at timestamptz,
  last_full_ok boolean,
  reinitialised_at timestamptz
);
insert into public.fz_audit_state (id) values (1) on conflict (id) do nothing;
create table if not exists public.fz_security_baseline (
  item text primary key,
  category text not null default 'grant' check (category in ('grant', 'standing')),
  status text not null default 'alerted' check (status in ('expected', 'alerted', 'acknowledged', 'revoked')),
  generation int not null default 1,                                     -- +1 each time a revoked item comes back (it alerts again)
  first_seen timestamptz not null default now(),
  last_seen timestamptz not null default now(),
  acknowledged_by text,
  acknowledged_at timestamptz
);
create table if not exists public.fz_security_fingerprints (            -- SECURITY DEFINER functions an API role can execute: body + settings
  sig text primary key,
  fp text not null,
  first_seen timestamptz not null default now(),
  changed_at timestamptz
);
create table if not exists public.fz_security_alerts (
  id bigint generated always as identity primary key,
  kind text not null check (kind in ('chain_break', 'new_privilege', 'standing', 'definer_changed', 'reinitialised')),
  item text not null,
  dedupe_key text not null unique,                                       -- type + first id: one problem alerts once
  detail jsonb not null default '{}'::jsonb,
  at timestamptz not null default now()
);
create table if not exists public.fz_token_registry (
  jti text primary key check (length(jti) between 4 and 200),
  identity text not null,
  issued_at timestamptz not null default now(),
  expires_at timestamptz not null,
  note text not null default '',
  registered_by text not null default 'owner',
  registered_at timestamptz not null default now()
);

do $$
declare t text;
begin
  foreach t in array array['fz_audit_chain', 'fz_audit_pending', 'fz_audit_state', 'fz_security_baseline', 'fz_security_fingerprints', 'fz_security_alerts', 'fz_token_registry'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from public, anon, authenticated, service_role, fz_jarvis, fz_office_agent, fz_auditor', t);
  end loop;
end $$;
grant select on public.fz_audit_chain, public.fz_audit_state, public.fz_security_baseline, public.fz_security_fingerprints, public.fz_security_alerts, public.fz_token_registry to service_role;
revoke all on sequence public.fz_audit_chain_seq_seq, public.fz_security_alerts_id_seq from public, anon, authenticated, service_role;

drop trigger if exists fz_audit_chain_append_only on public.fz_audit_chain;
create trigger fz_audit_chain_append_only before update or delete on public.fz_audit_chain for each row execute function public.fz_append_only();
drop trigger if exists fz_security_alerts_append_only on public.fz_security_alerts;
create trigger fz_security_alerts_append_only before update or delete on public.fz_security_alerts for each row execute function public.fz_append_only();
do $$
declare t text;
begin
  foreach t in array array['fz_audit_chain', 'fz_audit_state', 'fz_security_alerts', 'fz_security_baseline', 'fz_security_fingerprints', 'fz_token_registry'] loop
    execute format('drop trigger if exists %I on public.%I', t || '_no_truncate', t);
    execute format('create trigger %I before truncate on public.%I for each statement execute function public.fz_append_only()', t || '_no_truncate', t);
  end loop;
end $$;
drop trigger if exists fz_token_registry_owner on public.fz_token_registry;
create trigger fz_token_registry_owner before insert or update or delete on public.fz_token_registry for each row execute function public.fz_money_owner_only();

-- ---------------------------------------------------------------------------------------------------------------------------- the audit hash chain
create or replace function public.fz_audit_row_hash(p_id bigint, p_at timestamptz, p_actor text, p_action text, p_target text, p_detail jsonb) returns text
language sql immutable set search_path to 'pg_catalog' as $$
  select encode(sha256(convert_to(concat_ws('|', p_id::text, to_char(p_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'), coalesce(p_actor, ''), coalesce(p_action, ''),
                                            coalesce(p_target, ''), coalesce(p_detail::text, '')), 'UTF8')), 'hex')
$$;
revoke all on function public.fz_audit_row_hash(bigint, timestamptz, text, text, text, jsonb) from public, anon, authenticated;

create or replace function public.fz_audit_link(p_prev text, p_row text) returns text
language sql immutable set search_path to 'pg_catalog' as $$ select encode(sha256(convert_to(coalesce(p_prev, 'genesis') || ':' || p_row, 'UTF8')), 'hex') $$;
revoke all on function public.fz_audit_link(text, text) from public, anon, authenticated;

-- 1. OBSERVE every visible row above the head (hash + our time); 2. CHAIN, strictly by id, each row first seen at least 5 minutes ago (with the hash seen then); a hole
-- becomes a 'gap' link once a later id has been visible for 5 minutes. audit_log.at plays no part. Returns how many links were added. Service path / cron.
create or replace function public.fz_audit_chain_extend(p_limit integer default 5000) returns integer
language plpgsql security definer set search_path to 'pg_catalog' as $$
declare h public.fz_audit_chain; st public.fz_audit_state; k bigint; v_prev text; p public.fz_audit_pending; n int := 0; v_lim int := greatest(coalesce(p_limit, 5000), 1);
        v_max_ready bigint;
begin
  if coalesce(nullif(current_setting('role', true), ''), 'none') in ('fz_jarvis', 'fz_office_agent', 'fz_auditor') then
    raise exception 'the audit chain is built on the service path only' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(7334);
  select * into h from public.fz_audit_chain order by seq desc limit 1;
  insert into public.fz_audit_pending (audit_id, row_hash)
    select a.id, public.fz_audit_row_hash(a.id, a.at, a.actor, a.action, a.target, a.detail) from public.audit_log a
     where a.id > coalesce(h.audit_id, 0) order by a.id limit 50000
  on conflict (audit_id) do nothing;
  select * into st from public.fz_audit_state where id = 1 for update;
  if h.seq is null then
    k := (select min(audit_id) from public.fz_audit_pending where first_seen <= now() - interval '5 minutes');
    if k is null then return 0; end if;
    update public.fz_audit_state set genesis_id = k where id = 1;
  else
    k := h.audit_id + 1;
  end if;
  v_prev := h.chain_hash;
  select max(audit_id) into v_max_ready from public.fz_audit_pending where first_seen <= now() - interval '5 minutes';
  while n < v_lim and k <= coalesce(v_max_ready, 0) loop
    select * into p from public.fz_audit_pending where audit_id = k;
    if p.audit_id is not null then
      exit when p.first_seen > now() - interval '5 minutes';
      v_prev := public.fz_audit_link(v_prev, p.row_hash);
      insert into public.fz_audit_chain (audit_id, kind, row_hash, chain_hash) values (k, 'row', p.row_hash, v_prev);
      delete from public.fz_audit_pending where audit_id = k;            -- working buffer only (the chain now holds the hash)
    else
      v_prev := public.fz_audit_link(v_prev, 'gap');                     -- a later id has been visible for 5 minutes and this one never appeared
      insert into public.fz_audit_chain (audit_id, kind, row_hash, chain_hash) values (k, 'gap', 'gap', v_prev);
    end if;
    n := n + 1; k := k + 1;
  end loop;
  return n;
end $$;
revoke all on function public.fz_audit_chain_extend(integer) from public, anon, authenticated;

-- verifies from the checkpoint (incremental) or from the start (p_full; honoured only for the cron job / the owner's session / the signed-in owner). Always checks the
-- pending rows (changed since first seen), rows below genesis, and rows that appeared in gaps. Read-only: the watch stores the checkpoint.
create or replace function public.fz_audit_verify(p_full boolean default false) returns jsonb
language plpgsql stable security definer set search_path to 'pg_catalog' as $$
declare c record; a record; v_prev text; n bigint := 0; breaks jsonb := '[]'::jsonb; nb int := 0; st public.fz_audit_state; v_full boolean; v_from bigint; v_last_seq bigint; v_last_hash text;
        v_role text := coalesce(nullif(current_setting('role', true), ''), 'none'); v_x bigint;
begin
  select * into st from public.fz_audit_state where id = 1;
  v_full := coalesce(p_full, false) and (v_role in ('none', 'postgres') or coalesce(public.is_app_owner(), false));
  if not v_full and st.checkpoint_seq is not null then
    v_from := st.checkpoint_seq; v_prev := st.checkpoint_hash;
    if (select chain_hash from public.fz_audit_chain where seq = st.checkpoint_seq) is distinct from st.checkpoint_hash then
      nb := nb + 1; breaks := breaks || jsonb_build_object('problem', 'chain_edited', 'seq', st.checkpoint_seq, 'note', 'the checkpointed link changed');
    end if;
  else
    v_from := 0; v_prev := null;
  end if;
  for c in select * from public.fz_audit_chain where seq > v_from order by seq loop
    n := n + 1;
    select x.id, x.at, x.actor, x.action, x.target, x.detail into a from public.audit_log x where x.id = c.audit_id;
    if c.kind = 'row' then
      if a.id is null then nb := nb + 1; if nb <= 20 then breaks := breaks || jsonb_build_object('audit_id', c.audit_id, 'problem', 'deleted'); end if;
      elsif public.fz_audit_row_hash(a.id, a.at, a.actor, a.action, a.target, a.detail) <> c.row_hash then
        nb := nb + 1; if nb <= 20 then breaks := breaks || jsonb_build_object('audit_id', c.audit_id, 'problem', 'changed'); end if;
      end if;
    elsif a.id is not null then
      nb := nb + 1; if nb <= 20 then breaks := breaks || jsonb_build_object('audit_id', c.audit_id, 'problem', 'gap_filled', 'note', 'a row appeared later in a hole of the chain'); end if;
    end if;
    if public.fz_audit_link(v_prev, c.row_hash) <> c.chain_hash then
      nb := nb + 1; if nb <= 20 then breaks := breaks || jsonb_build_object('audit_id', c.audit_id, 'problem', 'chain_edited'); end if;
    end if;
    v_prev := c.chain_hash; v_last_seq := c.seq; v_last_hash := c.chain_hash;
  end loop;
  -- rows seen but not chained yet: changed or gone since first seen
  for c in select p.audit_id, p.row_hash, x.id, x.at, x.actor, x.action, x.target, x.detail from public.fz_audit_pending p left join public.audit_log x on x.id = p.audit_id order by p.audit_id loop
    if c.id is null then nb := nb + 1; if nb <= 20 then breaks := breaks || jsonb_build_object('audit_id', c.audit_id, 'problem', 'deleted', 'note', 'deleted before it was chained'); end if;
    elsif public.fz_audit_row_hash(c.id, c.at, c.actor, c.action, c.target, c.detail) <> c.row_hash then
      nb := nb + 1; if nb <= 20 then breaks := breaks || jsonb_build_object('audit_id', c.audit_id, 'problem', 'changed', 'note', 'changed before it was chained'); end if;
    end if;
  end loop;
  select count(*) into v_x from public.audit_log where id < st.genesis_id;
  if v_x > 0 then nb := nb + 1; breaks := breaks || jsonb_build_object('problem', 'below_genesis', 'rows', v_x, 'note', 'rows with an id below the first chained row'); end if;
  return jsonb_build_object('ok', nb = 0, 'full', v_full or st.checkpoint_seq is null, 'checked', n, 'breaks', breaks, 'break_count', nb,
                            'last_seq', coalesce(v_last_seq, st.checkpoint_seq), 'last_hash', coalesce(v_last_hash, st.checkpoint_hash),
                            'gaps', (select count(*) from public.fz_audit_chain where kind = 'gap'), 'genesis_id', st.genesis_id,
                            'head_hash', (select chain_hash from public.fz_audit_chain order by seq desc limit 1));
end $$;
revoke all on function public.fz_audit_verify(boolean) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------------------------------------- privileged items (every non-system schema)
-- category 'standing': always reported, never acknowledged (any anon / authenticated write, REFERENCES or TRIGGER; service_role UPDATE / DELETE / TRUNCATE on audit_log or ledger, until the owner
-- applies ops/proposals/audit_ledger_append_only.sql). 'grant': compared with the reviewed allowlist fz_expected_grants().
create or replace function public.fz_privileged_items() returns table (item text, category text)
language sql stable security definer set search_path to 'pg_catalog' as $$
  with watched as (select rolname, oid from pg_roles where rolname in ('anon', 'authenticated', 'fz_jarvis', 'fz_office_agent', 'fz_auditor', 'backup_reader')),
  rels as (select c.oid, c.relkind, c.relrowsecurity, n.nspname || '.' || c.relname as qn from pg_class c join pg_namespace n on n.oid = c.relnamespace
            where n.nspname !~ '^pg_' and n.nspname <> 'information_schema' and c.relkind in ('r', 'p', 'v', 'm', 'f'))
  select 'table:' || r.qn || ':' || w.rolname || ':' || p.priv, case when w.rolname in ('anon', 'authenticated') then 'standing' else 'grant' end   -- incl. REFERENCES / TRIGGER
    from rels r cross join watched w cross join unnest(array['INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER']) p (priv)
   where has_table_privilege(w.oid, r.oid, p.priv)
  union
  select 'column-write:' || r.qn || ':' || w.rolname, case when w.rolname in ('anon', 'authenticated') then 'standing' else 'grant' end
    from rels r cross join watched w
   where r.relkind in ('r', 'p') and not has_table_privilege(w.oid, r.oid, 'INSERT') and not has_table_privilege(w.oid, r.oid, 'UPDATE')
     and (has_any_column_privilege(w.oid, r.oid, 'INSERT') or has_any_column_privilege(w.oid, r.oid, 'UPDATE'))
  union
  select 'table-read:' || r.qn || ':' || w.rolname || case when r.relkind in ('r', 'p') and not r.relrowsecurity then ':rls-off' else '' end, 'grant'
    from rels r cross join watched w
   where w.rolname in ('anon', 'authenticated') and has_table_privilege(w.oid, r.oid, 'SELECT')
  union
  select 'table:public.' || t.t || ':service_role:' || p.priv, 'standing'
    from unnest(array['audit_log', 'ledger']) t (t) cross join unnest(array['UPDATE', 'DELETE', 'TRUNCATE']) p (priv)
   where to_regclass('public.' || t.t) is not null and exists (select 1 from pg_roles where rolname = 'service_role') and has_table_privilege('service_role', ('public.' || t.t)::regclass, p.priv)
  union
  select 'definer:' || n.nspname || '.' || p.oid::regprocedure::text || ':' || w.rolname, 'grant'
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace cross join watched w
   where n.nspname !~ '^pg_' and n.nspname <> 'information_schema' and p.prosecdef and has_function_privilege(w.oid, p.oid, 'EXECUTE')
  union
  select 'schema-create:' || n.nspname || ':' || w.rolname, case when w.rolname in ('anon', 'authenticated') then 'standing' else 'grant' end
    from pg_namespace n cross join watched w
   where n.nspname !~ '^pg_' and n.nspname <> 'information_schema' and has_schema_privilege(w.oid, n.oid, 'CREATE')
  union
  select 'role:' || r.rolname || ':' || a.attr, 'grant'
    from pg_roles r cross join lateral (values ('superuser', r.rolsuper), ('bypassrls', r.rolbypassrls), ('createrole', r.rolcreaterole), ('createdb', r.rolcreatedb)) a (attr, on_)
   where a.on_ and r.rolname in ('anon', 'authenticated', 'authenticator', 'fz_jarvis', 'fz_office_agent', 'fz_auditor', 'backup_reader')
  union
  select 'member:' || m.member::regrole::text || ':' || m.roleid::regrole::text, 'grant'
    from pg_auth_members m join pg_roles g on g.oid = m.roleid
   where g.rolname in ('service_role', 'postgres', 'supabase_admin') and m.member::regrole::text in ('anon', 'authenticated', 'fz_jarvis', 'fz_office_agent', 'fz_auditor', 'backup_reader')
$$;
revoke all on function public.fz_privileged_items() from public, anon, authenticated;

-- the reviewed allowlist: generated by scripts/expected_grants.py from the replica (whose ACLs equal the reviewed ops/ACL_MANIFEST_public.tsv), also in ops/expected_grants.tsv.
